insert into briefings (criterion_id, body, is_sample, sources, checked) values ('1.1', '["**What it measures.** Whether oversight of AI is written into the remit of the board or a named committee, reported on regularly, and recorded in the minutes.","**Why it matters.** AI arrives tool by tool, so no single moment puts the question to the board. Where nobody at the top is answerable, a system can turn people down, misprice or mislead for months before anyone with the authority to stop it hears of it. Customers, applicants and staff carry that harm.","**The UK position.** No UK law or code requires a board to oversee AI by name. Every director must exercise reasonable care, skill and diligence (Companies Act 2006, section 174), and every company must record minutes of its directors'' meetings (section 248). The UK Corporate Governance Code applies to listed companies on a comply or explain basis and does not mention AI. Its guidance, which is not prescriptive, names new technologies such as AI among the controls a board might treat as material, and says a responsibility delegated to a committee should be written into its terms of reference. It adds: \"The board retains ultimate responsibility for the risk management and internal control framework\". The Wates Principles say the same to large private companies.","**What good looks like.** AI named in terms of reference; regular reports against agreed thresholds; decisions and reasons minuted; the arrangement independently reviewed.","**Reading the answer.** Ask for the terms of reference and recent minutes. If AI appears only after an incident or a client''s question, oversight is reactive.","**A defensible figure.** In the Financial Reporting Council''s 2025 review of 100 listed companies'' annual reports, 86% mentioned AI, against around half in 2023 (page 44)."]'::jsonb, true, '[{"title":"Companies Act 2006, section 174: Duty to exercise reasonable care, skill and diligence","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/174","locator":"s.174(1) and (2)","access":"free"},{"title":"Companies Act 2006, section 248: Minutes of directors'' meetings","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/248","locator":"s.248(1) and (2)","access":"free"},{"title":"UK Corporate Governance Code 2024","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/documents/6709/UK_Corporate_Governance_Code_2024_a2hmQmY.pdf","locator":"Introduction (Application; Reporting on the Code), p.4-5; Principle O and Provision 29, p.12-13","access":"free"},{"title":"Corporate Governance Code Guidance","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/library/standards-codes-policy/corporate-governance/corporate-governance-code-guidance/","locator":"Paras 222-223 (Risk governance: delegation, responsibility and accountability); para 272 (Material controls); para 31 (board minutes); para 89 (committee terms of reference)","access":"free"},{"title":"Annual Review of Corporate Governance Reporting","publisher":"Financial Reporting Council","year":2025,"url":"https://www.frc.org.uk/documents/8893/Annual_Review_of_Corporate_Governance_Reporting_2025.pdf","locator":"p.44 (Artificial Intelligence); sample described on p.5","access":"free"},{"title":"The Wates Corporate Governance Principles for Large Private Companies","publisher":"Financial Reporting Council","year":2018,"url":"https://media.frc.org.uk/documents/The_Wates_Corporate_Governance_Principles_for_Large_Private_Companies.pdf","locator":"Principle Three (Director responsibilities), guidance on committees, p.16; scope and thresholds in the Introduction","access":"free"},{"title":"Supervisory Statement SS1/23: Model risk management principles for banks","publisher":"Bank of England, Prudential Regulation Authority","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2023/ss123.pdf","locator":"Principle 2.1 (Board of directors’ responsibilities), points (c)-(e), PDF p.14; scope at paras 1.2-1.3, PDF p.3","access":"free"},{"title":"Cyber Governance Code of Practice","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/cyber-governance-code-of-practice/cyber-governance-code-of-practice","locator":"Section A (Risk management), Action 2; Section E (Assurance and oversight), Action 1","access":"free"},{"title":"Artificial Intelligence Playbook for the UK Government","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/ai-playbook-for-the-uk-government/artificial-intelligence-playbook-for-the-uk-government-html","locator":"Governance section: AI governance board or AI representation on an existing board","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"GOVERN 2.3, Table 1, p.23","access":"free"}]'::jsonb, '2026-10-02')
