insert into briefings (criterion_id, body, is_sample, sources, checked) values ('1.4', '["**What it measures.** Whether there is one maintained list of every AI system in use, including AI bought in and AI built into other software, with purpose, owner, data and risk recorded for each.","**Why it matters.** A system that is on no list has no owner, no risk assessment and no review. If it treats people unfairly, nobody is looking, and nobody can tell the person affected that AI was involved.","**The UK position.** No UK law requires an AI register by name. The firmest expectations are sectoral. The Prudential Regulation Authority expects banks with internal model approval to keep a firm-wide model inventory covering models developed in-house or bought from vendors. Central government departments must publish a record of each algorithmic tool that significantly influences decisions affecting the public, and guidance asks them to keep an internal inventory as well: \"A live inventory will help your team, your organisation and your stakeholders understand the scope and scale of AI usage.\" For business, the government''s voluntary code on AI cyber security calls for a comprehensive inventory of assets, and its draft self-assessment tool starts with the system record, including documentation from third-party providers.","**What good looks like.** A complete register kept current: systems added through procurement and software change, entries reviewed on a set cycle, the register independently checked.","**Reading the answer.** Ask how the last three systems came to be on the list. A register compiled once is a snapshot. Features switched on inside software already licensed are easily missed.","**A defensible figure.** In the National Audit Office''s survey, eight of 32 government bodies that had deployed AI said they were always or usually compliant with the government''s transparency recording standard (March 2024, paragraph 3.20)."]'::jsonb, false, '[{"title":"Artificial Intelligence Playbook for the UK Government","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/ai-playbook-for-the-uk-government/artificial-intelligence-playbook-for-the-uk-government-html","locator":"Governance section: \"Creating an AI systems inventory\"","access":"free"},{"title":"Algorithmic Transparency Recording Standard: guidance for public sector bodies","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/guidance-for-organisations-using-the-algorithmic-transparency-recording-standard/algorithmic-transparency-recording-standard-guidance-for-public-sector-bodies","locator":"Section 2 (ATRS purpose and scope); section 2.1.4 (third party involvement)","access":"free"},{"title":"Use of artificial intelligence in government (HC 612)","publisher":"National Audit Office","year":2024,"url":"https://www.nao.org.uk/wp-content/uploads/2024/03/use-of-artificial-intelligence-in-government.pdf","locator":"Para 3.20, p.40; summary para 17, p.10","access":"free"},{"title":"Supervisory Statement SS1/23: Model risk management principles for banks","publisher":"Bank of England, Prudential Regulation Authority","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2023/ss123.pdf","locator":"Principle 1.2 (Model inventory), points (a)-(c), PDF p.11-12; para 1.3, PDF p.3","access":"free"},{"title":"AI Management Essentials tool (consultation version, accessible)","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/consultations/ai-management-essentials-tool/ai-management-essentials-tool-accessible","locator":"Section 1 (AI system record), questions 1.1-1.5","access":"free"},{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Principle 5 (Identify, track and protect your assets), provision 5.1","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"GOVERN 1.6, Table 1, p.23","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 49: Registration","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-49","locator":"Art. 49(1)-(3) and (5)","access":"free"},{"title":"FS2/23: Artificial Intelligence and Machine Learning (feedback statement)","publisher":"Bank of England, Prudential Regulation Authority and Financial Conduct Authority","year":2023,"url":"https://www.bankofengland.co.uk/prudential-regulation/publication/2023/october/artificial-intelligence-and-machine-learning","locator":"Para 4.11 (responses on model risk management)","access":"free"}]'::jsonb, '2026-10-02')
