insert into briefings (criterion_id, body, is_sample, sources, checked) values ('1.5', '["**What it measures.** Whether bought-in AI is examined before adoption and for as long as it is used: questions asked, answers tested, terms written into the contract, and a way out if the supplier fails.","**Why it matters.** When a bought tool gets a decision wrong, the person refused a job, a loan or a service has no dealings with the supplier and cannot see inside the product. If the buyer never checked, nobody did.","**The UK position.** Responsibility stays with the buyer. Government has said it is common for the law to place liability on the last actor in the chain. The Prudential Regulation Authority tells banks and insurers: \"Firms that enter into outsourcing arrangements remain fully accountable for complying with all their regulatory obligations.\" It expects due diligence on every third-party arrangement and, for material outsourcing, audit rights and a tested exit plan. A public body letting a contract above £5 million must generally set and publish at least three key performance indicators. Elsewhere, beyond data protection duties, the expectations are guidance.","**What good looks like.** The Information Commission (ICO) audit toolkit, under review, expects due diligence on accuracy and bias before purchase. National Cyber Security Centre guidance says to build a right to audit into contracts and to exercise it.","**Reading the answer.** The usual gap is AI inside ordinary software, bought without anyone treating it as an AI decision. A high answer needs evidence that a supplier was reassessed after a change.","**A defensible figure.** In the 2024 Bank of England and Financial Conduct Authority survey, third-party implementations made up 65% of AI use cases in human resources and 64% in risk and compliance; across all areas in 2022 the share was 17%."]'::jsonb, false, '[{"title":"SS2/21: Outsourcing and third party risk management (November 2024 update)","publisher":"Bank of England, Prudential Regulation Authority","year":2024,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2024/ss221-november-2024-update.pdf","locator":"Paras 2.4-2.6 (non-outsourcing third party arrangements, including off-the-shelf machine learning models), 4.3 (board accountability), 5.15-5.17 (due diligence), 8.3-8.4 (access, audit and information rights), 10.1 and 10.19 (exit plans)","access":"free"},{"title":"Artificial intelligence in UK financial services - 2024","publisher":"Bank of England and Financial Conduct Authority","year":2024,"url":"https://www.bankofengland.co.uk/report/2024/artificial-intelligence-in-uk-financial-services-2024","locator":"Section 2.8 (third-party implementation, Chart 9); executive summary (''Third-party exposure''); section 1.2 (118 responses)","access":"free"},{"title":"Procurement Act 2023, section 52: Key performance indicators","publisher":"legislation.gov.uk","year":2023,"url":"https://www.legislation.gov.uk/ukpga/2023/54/section/52","locator":"s.52(1)-(4), (6); commencement note I2 (in force 24 February 2025). Read with s.71(2) (assessment at least once in every twelve months; in force 1 January 2026 for specified purposes)","access":"free"},{"title":"Supply chain security guidance: III. Check your arrangements","publisher":"National Cyber Security Centre","year":2019,"url":"https://www.ncsc.gov.uk/collection/supply-chain-security/principles-supply-chain-security/check-your-arrangements","locator":"Principle 10 (''Build assurance activities into your supply chain management''); page shows ''Reviewed 22 October 2025''","access":"free"},{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Principle 7 (''Secure your supply chain''), provisions 7.1-7.4","access":"free"},{"title":"Artificial Intelligence Playbook for the UK Government","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/ai-playbook-for-the-uk-government/artificial-intelligence-playbook-for-the-uk-government-html","locator":"Principle 8 (''You work with commercial colleagues from the start''); section ''Buying AI'' (''Specifying your requirements'', ''Aligning procurement and ethics'')","access":"free"},{"title":"Data protection audit framework, Artificial intelligence toolkit: Contracts and third parties","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/artificial-intelligence/contracts-and-third-parties/","locator":"Second control measure (due diligence before procuring) and third control measure (written contracts)","access":"free"},{"title":"A pro-innovation approach to AI regulation: government response","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/consultations/ai-regulation-a-pro-innovation-approach-policy-proposals/outcome/a-pro-innovation-approach-to-ai-regulation-government-response","locator":"Section 5.2, paragraph 66 and Case study 1 (''Liability as a barrier to AI adoption in the UK''); footnote 76","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Table 1, GOVERN 6, 6.1 and 6.2 (document page 24; page 29 of the PDF)","access":"free"},{"title":"Guidelines for AI procurement","publisher":"Office for Artificial Intelligence","year":2020,"url":"https://www.gov.uk/government/publications/guidelines-for-ai-procurement/guidelines-for-ai-procurement","locator":"Top 10 considerations, items 8 and 10; section 4 (''Contract Implementation and Ongoing management'')","access":"free"}]'::jsonb, '2026-10-02')
