insert into briefings (criterion_id, body, is_sample, sources, checked) values ('1.6', '["**What it measures.** Whether someone is responsible for watching the rules that govern the organisation''s AI, on a set rhythm, with a record of what changed, what it meant and what was done.","**Why it matters.** AI rules now change in stages and by sector. When an organisation misses a change, the people its systems decide about go without a protection the law has just given them, and they are the last to find out.","**The UK position.** There is no single AI statute to watch. In February 2024 the government kept to existing law applied by existing regulators, while saying: \"The challenges posed by AI will ultimately require legislative action in every country once understanding of risk has matured.\" The King''s Speech of July 2024 promised to seek legislation for the most powerful models; the speech of May 2026, as published, does not mention artificial intelligence. The Information Commission (ICO) says the 2025 data protection changes are now all in force. For those trading into the European Union, the European Commission''s copy of the AI Act, amended in July 2026, applies the main high-risk rules from 2 December 2027.","**What good looks like.** A named owner; a short list of the instruments that matter; a fixed review date; a log of each change, its assessed effect and the action taken; the board told before a deadline, not after.","**Reading the answer.** Newsletters with no owner are reading, not scanning. Ask for the log entry for the last change and how long the response took.","**A defensible figure.** The sixth set of commencement regulations for the Data (Use and Access) Act 2025 alone brought provisions into force on two days, 5 February and 19 June 2026."]'::jsonb, false, '[{"title":"A pro-innovation approach to AI regulation: government response","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/consultations/ai-regulation-a-pro-innovation-approach-policy-proposals/outcome/a-pro-innovation-approach-to-ai-regulation-government-response","locator":"Ministerial foreword; paragraphs 12, 15, 17 and 76; section 5.1.2 (central function, horizon scanning)","access":"free"},{"title":"The King''s Speech 2024","publisher":"Prime Minister''s Office, 10 Downing Street","year":2024,"url":"https://www.gov.uk/government/speeches/the-kings-speech-2024","locator":"Paragraph following the Employment Rights Bill","access":"free"},{"title":"The King''s Speech 2026","publisher":"Prime Minister''s Office, 10 Downing Street","year":2026,"url":"https://www.gov.uk/government/speeches/the-kings-speech-2026","locator":"Whole speech searched for ''artificial intelligence'' and ''AI'': no occurrence. Passage quoted is the Regulating for Growth Bill","access":"free"},{"title":"Regulators'' strategic approaches to AI","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/publications/regulators-strategic-approaches-to-ai/regulators-strategic-approaches-to-ai","locator":"Introductory text and the list ''Regulator updates''","access":"free"},{"title":"AI and the FCA: our approach","publisher":"Financial Conduct Authority","year":2025,"url":"https://www.fca.org.uk/firms/innovation/ai-approach","locator":"Opening section; ''How do our current rules apply?''; page updates (last updated 2 October 2026, editorial amendment)","access":"free"},{"title":"Data (Use and Access) Act 2025","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/about-the-ico/what-we-do/legislation-we-cover/data-use-and-access-act-2025/","locator":"Opening paragraph; link to ''Our plans for new and updated guidance''","access":"free"},{"title":"The Data (Use and Access) Act 2025 (Commencement No. 6 and Transitional and Saving Provisions) Regulations 2026, S.I. 2026/82","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/uksi/2026/82/made","locator":"Regulations 2 (5 February 2026, including reg. 2(j), section 80, automated decision-making), 3 (19 June 2026) and 5 (saving for decisions taken before 5 February 2026)","access":"free"},{"title":"AI Act, Article 113: Entry into force and application (AI Act Service Desk copy)","publisher":"European Commission","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-113","locator":"Article 113, points (a)-(d), marked AMENDED and NEW; read with the Service Desk timeline page and the Commission''s ''AI Act'' policy page (''Application timeline'')","access":"free"},{"title":"AI and Digital Hub 2024/5","publisher":"Digital Regulation Cooperation Forum","year":2025,"url":"https://www.drcf.org.uk/ai-and-digital-hub","locator":"Opening statement and list of eight case studies; FAQs","access":"free"},{"title":"UK Corporate Governance Code 2024","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/documents/6709/UK_Corporate_Governance_Code_2024_a2hmQmY.pdf","locator":"Provision 28 (page 13 of the document); Introduction, ''Reporting on the Code'' (activities and outcomes); Principle C","access":"free"}]'::jsonb, '2026-10-02')
