insert into briefings (criterion_id, body, is_sample, sources, checked) values ('1.8', '["**What it measures.** Whether the organisation can show, from records made at the time, how each AI system came to be approved, on what evidence, by whom, and what has been reviewed since.","**Why it matters.** A person harmed by an AI decision can only have it examined if a record exists of what was decided and why. Without one the mistake cannot be traced, nobody can be held to account, and the board cannot show that it weighed the people affected.","**The UK position.** Every company must record minutes of all proceedings at directors'' meetings; authenticated minutes are evidence of what took place. Directors must have regard to employees, customers and the community, and large companies must report how they did so. No statute gives a safe harbour for good paperwork: a court may, at its discretion, relieve a director who acted honestly and reasonably. In the Business and Property Courts a party must take reasonable steps to preserve documents once it knows it may face proceedings, and a document is defined widely: \"It also extends to metadata, and other embedded data which is not typically visible on screen or a printout.\" A file written up afterwards carries its own date.","**What good looks like.** One file per system: purpose, approval and conditions, risk and impact assessments, supplier checks, test results, incidents, reviews.","**Reading the answer.** Ask for one system''s file and time how long it takes to produce. Scattered records, and records rebuilt after the event, are the two usual failures.","**A defensible figure.** Minutes of directors'' meetings must be kept for at least ten years from the date of the meeting (Companies Act 2006, section 248)."]'::jsonb, false, '[{"title":"Companies Act 2006, section 248: Minutes of directors'' meetings","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/248","locator":"s.248(1)-(4)","access":"free"},{"title":"Companies Act 2006, section 249: Minutes as evidence","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/249","locator":"s.249(1)-(2)","access":"free"},{"title":"Companies Act 2006, section 172: Duty to promote the success of the company","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/172","locator":"s.172(1)(a)-(f)","access":"free"},{"title":"Companies Act 2006, section 414CZA: Section 172(1) statement","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/414CZA","locator":"s.414CZA(1)-(2); note F2 (inserted by S.I. 2018/860)","access":"free"},{"title":"Companies Act 2006, section 1157: Power of court to grant relief in certain cases","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/1157","locator":"s.1157(1)-(2)","access":"free"},{"title":"Practice Direction 57AD: Disclosure in the Business and Property Courts","publisher":"Ministry of Justice","year":2022,"url":"https://www.justice.gov.uk/courts/procedure-rules/civil/rules/part-57a-business-and-property-courts/practice-direction-57ad-disclosure-in-the-business-and-property-courts","locator":"Paras 2.2, 2.5-2.6 (meaning of document), 3.1 (disclosure duties), 4.1-4.5 (preservation), 13.1 (native format, metadata)","access":"free"},{"title":"Algorithmic Transparency Recording Standard: guidance for public sector bodies","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/guidance-for-organisations-using-the-algorithmic-transparency-recording-standard/algorithmic-transparency-recording-standard-guidance-for-public-sector-bodies","locator":"Section 2 (''ATRS purpose and scope''); sections 5-13 (the template tiers)","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Section 5.1 (GOVERN), document page 22 (page 27 of the PDF); MAP 2.2; MEASURE 3.1","access":"free"},{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Principle 8 (''Document your data, models and prompts''), provisions 8.1 and 8.1.1","access":"free"},{"title":"AI Act, Article 26: Obligations of deployers of high-risk AI systems (AI Act Service Desk copy)","publisher":"European Commission","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-26","locator":"Article 26(5)-(6); ''About this text'' notice. Article 73 (serious incident reporting) read alongside","access":"free"}]'::jsonb, '2026-10-02')
