insert into briefings (criterion_id, body, is_sample, sources, checked) values ('2.1', '["**What it measures.** Whether every AI system in use, including tools bought in or embedded in other software, has been assigned a risk tier by a written method, with the reasoning kept.","**Why it matters.** A tier decides how much care a system gets. A tool that screens job applicants or scores credit, left unclassified, gets the oversight given to a spellchecker, and the people it sifts bear errors nobody was looking for.","**The UK position.** UK law sets no AI risk tiers. The 2023 white paper said: \"We will not assign rules or risk levels to entire sectors or technologies.\" The Prudential Regulation Authority does expect banks to tier every model, vendor models included. The EU''s AI Act does set classes in law: prohibited practices, and high-risk uses listed in an annex, among them recruitment, credit scoring and education. It reaches organisations outside the Union where a system''s output is used there. Its prohibitions have applied since 2 February 2025, with two more from 2 December 2026. Within the listed areas, a system that profiles people always counts as high-risk.","**What good looks like.** One method applied to the whole register; tier and reasons recorded for each system; procured and embedded tools included; re-tiering when a use or a supplier''s feature changes; independent review of the method.","**Reading the answer.** A claim to have no high-risk AI is a finding only if someone checked. Ask for the recruitment platform''s tier and reasoning.","**A defensible figure.** In the Bank of England and Financial Conduct Authority''s 2024 survey of financial firms (118 responses), a third of AI use cases were third-party implementations; firms rated 62% of use cases low materiality and 16% high."]'::jsonb, true, '[{"title":"Regulation (EU) 2024/1689 (AI Act), Article 6: Classification rules for high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-6","locator":"Art. 6(1), (1a)-(1c) (NEW), 6(2), 6(3) and 6(4)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Annex III: High-risk AI systems referred to in Article 6(2)","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/annex-3","locator":"Annex III, points 1 to 8; point 3 (education), point 4(a) (recruitment), point 5(b) (credit)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 5: Prohibited AI practices","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-5","locator":"Art. 5(1)(a)-(h); points (ba) and (bb) and paragraphs 1a and 1b marked NEW","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 113: Entry into force and application","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-113","locator":"Art. 113, third paragraph, points (a) and (c), both marked AMENDED","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 2: Scope","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-2","locator":"Art. 2(1)(a)-(c)","access":"free"},{"title":"A pro-innovation approach to AI regulation (white paper)","publisher":"Department for Science, Innovation and Technology","year":2023,"url":"https://www.gov.uk/government/publications/ai-regulation-a-pro-innovation-approach/white-paper","locator":"Section 3.2.2, paragraph 45","access":"free"},{"title":"SS1/23 Model risk management principles for banks","publisher":"Bank of England, Prudential Regulation Authority","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2023/ss123.pdf","locator":"Principle 1.3 ''Model tiering'', points (a)-(e), PDF p.12-13; Principle 1.2 ''Model inventory''; paragraphs 1.2-1.3 (scope) and 1.5 (effective date)","access":"free"},{"title":"Artificial intelligence in UK financial services - 2024","publisher":"Bank of England and Financial Conduct Authority","year":2024,"url":"https://www.bankofengland.co.uk/report/2024/artificial-intelligence-in-uk-financial-services-2024","locator":"Executive summary, ''Third-party exposure'' and ''Materiality''; section 1.2 ''Methodology''","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Section 1.2.3 ''Risk Prioritization'', p.7; MAP 4.1 and 4.2, Table 2, p.27; GOVERN 6.1, Table 1, p.24","access":"free"},{"title":"International AI Safety Report 2026","publisher":"International AI Safety Report (chair: Yoshua Bengio)","year":2026,"url":"https://internationalaisafetyreport.org/publication/international-ai-safety-report-2026","locator":"Executive summary, ''Real-world evidence for several risks is growing''; chapter 2 introduction; section 3.2, Table 3.1 and ''Risk thresholds/risk tiers''","access":"free"}]'::jsonb, '2026-10-02')
