insert into briefings (criterion_id, body, is_sample, sources, checked) values ('2.2', '["**What it measures.** Whether the board has written down which uses of AI it will pursue, which it will allow only with controls, and which it refuses, in terms specific enough to settle a real decision.","**Why it matters.** Without a stated position, the line is drawn by whoever buys the tool. The people affected, a customer refused credit or an employee scored by software, then bear a level of error that no director chose to accept.","**The UK position.** No UK law requires an AI risk appetite statement. The UK Corporate Governance Code 2024 asks boards of listed companies, on a comply or explain basis, to determine the principal risks the company is willing to take. The accompanying guidance says the board should approve the appetite and names artificial intelligence among technology risks whose controls may be material. The Prudential Regulation Authority expects a bank''s board to set a model risk appetite, including tolerance for errors. On personal data the Information Commission (ICO) is direct: \"It is unrealistic to adopt a ‘zero tolerance’ approach to risks to rights and freedoms, and indeed the law does not require you to do so.\" Compliance is still required, so appetite starts where the law stops.","**What good looks like.** A board-approved statement by category of use; tolerances that can be measured, such as error rates; breaches escalated; review on a set cycle and after incidents.","**Reading the answer.** Ask someone proposing a new AI use whether it sits inside appetite. If they have to ask, the statement is not working.","**A defensible figure.** Under the EU''s AI Act, prohibited practices carry fines of up to EUR 35,000,000 or 7% of worldwide annual turnover, whichever is higher (Article 99(3))."]'::jsonb, false, '[{"title":"UK Corporate Governance Code 2024","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/documents/6709/UK_Corporate_Governance_Code_2024_a2hmQmY.pdf","locator":"Section 4, Principle O (PDF p.13); Provisions 28 and 29 (PDF p.14)","access":"free"},{"title":"Corporate Governance Code Guidance","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/library/standards-codes-policy/corporate-governance/corporate-governance-code-guidance/","locator":"Paragraphs 215 and 239-241 (''Risk appetite''), 250 and 272","access":"free"},{"title":"The Orange Book: Management of Risk - Principles and Concepts","publisher":"HM Treasury, Government Finance Function","year":2023,"url":"https://www.gov.uk/government/publications/orange-book/the-orange-book-management-of-risk-principles-and-concepts","locator":"Section A, paragraph A3; Section D, paragraphs D6, D14 and D15","access":"free"},{"title":"SS1/23 Model risk management principles for banks","publisher":"Bank of England, Prudential Regulation Authority","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2023/ss123.pdf","locator":"Principle 2.1 ''Board of directors’ responsibilities'', points (c) and (d), PDF p.14","access":"free"},{"title":"Guidance on AI and data protection: What are the accountability and governance implications of AI?","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/what-are-the-accountability-and-governance-implications-of-ai/","locator":"Section ''How should we set a meaningful risk appetite?''","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Section 1.2.2 ''Risk Tolerance'', p.7; GOVERN 1.3, Table 1, p.22; MAP 1.5, Table 2, p.26","access":"free"},{"title":"International AI Safety Report 2026","publisher":"International AI Safety Report (chair: Yoshua Bengio)","year":2026,"url":"https://internationalaisafetyreport.org/publication/international-ai-safety-report-2026","locator":"Section 3.2 ''Risk management practices'', entries ''Risk thresholds/risk tiers'' and ''Risk tolerance''","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 99: Penalties","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-99","locator":"Art. 99(3)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 5: Prohibited AI practices","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-5","locator":"Art. 5(1)(f)","access":"free"},{"title":"Risk appetite and tolerance","publisher":"Institute of Risk Management","year":2026,"url":"https://www.theirm.org/what-we-say/thought-leadership/risk-appetite-and-tolerance/","locator":"Opening paragraph of the page","access":"free"}]'::jsonb, '2026-10-02')
