insert into briefings (criterion_id, body, is_sample, sources, checked) values ('2.3', '["**What it measures.** Whether the effect of an AI system on people''s data and on their wider rights is assessed before it goes live, as one joined exercise.","**Why it matters.** Privacy is one of several things an AI system can damage. A person can be wrongly denied a benefit, treated worse because of race or disability, or left with no way to complain. An assessment that looks only at data handling misses those harms; one done after launch protects nobody.","**The UK position.** UK GDPR Article 35 requires an assessment before high-risk processing. The Information Commission (ICO) reads the risks widely: \"This includes risks to privacy and data protection rights, but also effects on other fundamental rights and interests.\" UK law has no separate fundamental rights assessment for AI. Public authorities must have due regard to equality and may not act incompatibly with Convention rights. The EU''s AI Act adds a fundamental rights assessment for public bodies, private providers of public services, and deployers of credit-scoring and life and health insurance pricing systems. It must be done before deployment and its results notified to the market surveillance authority; it may cross-refer to the data protection assessment.","**What good looks like.** Screening for every deployment; one file covering data protection, equality and other rights; the people affected and the specific harms named; complaint routes set; both assessments dated before go-live and updated on change.","**Reading the answer.** Ask which rights other than privacy the last assessment considered, and who was consulted.","**A defensible figure.** High-risk systems already in use when the rules begin are caught only if significantly changed, but those intended for public authorities must comply by 2 August 2030 (AI Act Article 111(2))."]'::jsonb, false, '[{"title":"UK GDPR, Article 35: Data protection impact assessment","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/35","locator":"Art. 35(1) and 35(7)(c)-(d); note F2","access":"free"},{"title":"Data protection impact assessments: What is a DPIA?","publisher":"Information Commissioner''s Office","year":2025,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/accountability-and-governance/data-protection-impact-assessments-dpias/what-is-a-dpia/","locator":"Section ''What kind of ‘risk’ do they assess?''","access":"free"},{"title":"Guidance on AI and data protection: What are the accountability and governance implications of AI?","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/what-are-the-accountability-and-governance-implications-of-ai/","locator":"Section ''What do we need to consider when undertaking data protection impact assessments for AI?'', paragraph beginning ''In addition to conducting a DPIA''","access":"free"},{"title":"Equality Act 2010, section 149: Public sector equality duty","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/149","locator":"s.149(1)","access":"free"},{"title":"Human Rights Act 1998, section 6: Acts of public authorities","publisher":"legislation.gov.uk","year":1998,"url":"https://www.legislation.gov.uk/ukpga/1998/42/section/6","locator":"s.6(1)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 27: Fundamental rights impact assessment for high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-27","locator":"Art. 27(1)(a)-(f), 27(2), 27(3); 27(4) and 27(5) marked AMENDED","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Recital 96","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/recital-96","locator":"Recital 96","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 26: Obligations of deployers of high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-26","locator":"Art. 26(9)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 111: AI systems already placed on the market or put into service","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-111","locator":"Art. 111(2), marked AMENDED","access":"free"},{"title":"Algorithmic Transparency Recording Standard: guidance for public sector bodies","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/guidance-for-organisations-using-the-algorithmic-transparency-recording-standard/algorithmic-transparency-recording-standard-guidance-for-public-sector-bodies","locator":"Section 13 ''Risks, Mitigations and Impact Assessments''","access":"free"}]'::jsonb, '2026-10-02')
