insert into briefings (criterion_id, body, is_sample, sources, checked) values ('2.4', '["**What it measures.** Whether AI bought from others is run as its provider specifies, on checked input data, with its behaviour watched and its logs kept.","**Why it matters.** A supplier''s assurances hold only inside the conditions it tested. Outside them, or fed poor data, a system can give confident wrong answers about real people: applicants, patients, borrowers. Without logs nobody can show what happened, or put it right.","**The UK position.** No UK statute sets these duties for AI as such. Government''s voluntary AI cyber security code says of organisations that deploy AI: \"System Operators shall log system and user actions to support security compliance, incident investigations, and vulnerability remediation.\" The Information Commission (ICO) says bought-in AI should be reviewed regularly, with the ability to switch provider. The Prudential Regulation Authority expects banks to validate and monitor their own use of vendor models. The EU''s AI Act makes this law for deployers of high-risk systems from 2 December 2027: use in accordance with the instructions, input data that is relevant and sufficiently representative where the deployer controls it, monitoring, suspension where a risk appears, and retention of logs. A deployer whose change of intended purpose makes a system high-risk is treated as its provider.","**What good looks like.** The instructions read and their limits written into procedure; input checks; a named person monitoring; a tested way to stop the system; a retention period set; findings fed back to suppliers.","**Reading the answer.** Ask for last month''s logs and who read them.","**A defensible figure.** Logs under the deployer''s control must be kept for at least six months (Article 26(6)). In a 2024 survey of UK financial firms, 46% reported only partial understanding of their AI."]'::jsonb, false, '[{"title":"Regulation (EU) 2024/1689 (AI Act), Article 26: Obligations of deployers of high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-26","locator":"Art. 26(1), (4), (5) and (6)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 13: Transparency and provision of information to deployers","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-13","locator":"Art. 13(2) and 13(3)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 25: Responsibilities along the AI value chain","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-25","locator":"Art. 25(1)(c)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 113: Entry into force and application","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-113","locator":"Art. 113, third paragraph, point (c)(i), marked AMENDED","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 99: Penalties","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-99","locator":"Art. 99(4)(e)","access":"free"},{"title":"Guidance on AI and data protection: What are the accountability and governance implications of AI?","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/what-are-the-accountability-and-governance-implications-of-ai/","locator":"Section ''Outsourcing and third-party AI systems''","access":"free"},{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Principle 12 ''Monitor your system’s behaviour'', provisions 12.1-12.4; definition of ''System Operators''","access":"free"},{"title":"SS1/23 Model risk management principles for banks","publisher":"Bank of England, Prudential Regulation Authority","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2023/ss123.pdf","locator":"Principle 2.6 ''Use of externally developed models, third-party vendor products'', points (a) and (b), PDF p.19","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"MANAGE 3.1, Table 4, p.32; MEASURE 2.4, Table 3, p.29; MANAGE 4.1, Table 4, p.33","access":"free"},{"title":"Artificial intelligence in UK financial services - 2024","publisher":"Bank of England and Financial Conduct Authority","year":2024,"url":"https://www.bankofengland.co.uk/report/2024/artificial-intelligence-in-uk-financial-services-2024","locator":"Executive summary, ''Understanding of AI systems''","access":"free"}]'::jsonb, '2026-10-02')
