insert into briefings (criterion_id, body, is_sample, sources, checked) values ('2.7', '["**What it measures.** Whether the risk of each AI system is looked at again after it goes live, on a schedule and whenever something material changes.","**Why it matters.** A system that was fair and accurate at purchase can stop being so as the people, the data or the model change. Nobody inside notices. The people on the receiving end do: they are scored against a world that no longer exists.","**The UK position.** UK GDPR Article 35 requires a controller to review processing against its impact assessment at least when the risk changes. The Information Commission (ICO), in AI guidance now under review, says: \"After deployment, you should implement monitoring, the frequency of which should be proportional to the impact an incorrect output may have on individuals.\" It also expects documented thresholds for when a model must be retrained. For banks with internal model approval, the Prudential Regulation Authority expects ongoing performance monitoring, including of supplier models, at a frequency set by each model''s tier. The EU AI Act describes risk management for high-risk systems as a continuous process across the whole lifecycle and requires deployers to monitor operation.","**What good looks like.** Each system has a review date and named triggers: a model or supplier change, a new use, an incident, a change in the law. Thresholds are written down. Reviews are minuted and feed treatment decisions and board reports.","**Reading the answer.** Ask when the most consequential system last changed and whether anyone reassessed it. A review that rereads the document and not the system does not count.","**A defensible figure.** No defensible figure was found."]'::jsonb, false, '[{"title":"UK GDPR, Article 35: Data protection impact assessment","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/35","locator":"Art. 35(11); Art. 35(7)(d)","access":"free"},{"title":"Guidance on AI and data protection: What do we need to know about accuracy and statistical accuracy?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/what-do-we-need-to-know-about-accuracy-and-statistical-accuracy/","locator":"Section ''How should we define and prioritise different statistical accuracy measures?'' (closing paragraphs on concept / model drift); section ''What should we do about statistical accuracy post-deployment?'', first paragraph","access":"free"},{"title":"Data protection impact assessments: How do we do a DPIA?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/accountability-and-governance/data-protection-impact-assessments-dpias/how-do-we-do-a-dpia/","locator":"Section ''Step 7: How do we conclude our DPIA?'', final paragraph (keep under review)","access":"free"},{"title":"SS1/23: Model risk management principles for banks","publisher":"Prudential Regulation Authority, Bank of England","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2023/ss123.pdf","locator":"Principle 4.4 (a) to (e), pp.26-27; Principle 2.6(b)(iii) on vendor models, p.19","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 9: Risk management system","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-9","locator":"Art. 9(1) and 9(2)(a) to (d)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 72: Post-market monitoring by providers and post-market monitoring plan for high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-72","locator":"Art. 72(1), (2) and (3) (paragraph 3 marked AMENDED)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 26: Obligations of deployers of high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-26","locator":"Art. 26(5), first sentence and second subparagraph","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Table 4, MANAGE 4.1, p.33 (PDF page 38); Table 1, GOVERN 1.5, p.23 (PDF page 28); Appendix B, p.38 (PDF page 43)","access":"free"},{"title":"The Orange Book: Management of Risk, Principles and Concepts","publisher":"HM Treasury and Government Finance Function","year":2023,"url":"https://assets.publishing.service.gov.uk/media/6453acadc33b460012f5e6b8/HMT_Orange_Book_May_2023.pdf","locator":"Section D, ''Risk monitoring'', paragraphs D10 and D11, pp.23-24 (PDF pages 25-26)","access":"free"},{"title":"A pro-innovation approach to AI regulation (white paper)","publisher":"Department for Science, Innovation and Technology","year":2023,"url":"https://www.gov.uk/government/publications/ai-regulation-a-pro-innovation-approach/white-paper","locator":"Section 3.2.3, principle ''Safety, security and robustness'', definition and rationale","access":"free"}]'::jsonb, '2026-10-02')
