insert into briefings (criterion_id, body, is_sample, sources, checked) values ('2.8', '["**What it measures.** Whether the depth of risk work matches the organisation''s size and the stakes of each system, and whether there is a record to show for it.","**Why it matters.** With too little, people harmed by a system find that nobody can show what was considered or why. With too much, a small firm spends its effort on paperwork for trivial tools.","**The UK position.** UK GDPR Article 24 scales the duty: measures must reflect the nature, scope, context and purposes of processing and its risks, and the controller must be able to demonstrate compliance. The Information Commission (ICO), in guidance under review, says: \"Your governance and risk management capabilities need to be proportionate to your use of AI.\" Its audit framework says no single approach fits all. Government policy since 2023 is that burdens should not fall disproportionately on smaller companies. In the EU, the AI Act as amended in 2026 lets small and medium-sized enterprises and small mid-caps give technical documentation in a simplified form. The Commission''s form was not found published. Simplification changes the format, not the level of protection.","**What good looks like.** One file per system, as deep as the stakes: what it is, how it was classed and why, the treatment decisions, the controls, incidents and reviews. It is kept current and can be produced on request.","**Reading the answer.** Ask for the file on the highest-stakes system. Lean is fine. Empty or stale is not.","**A defensible figure.** The European Commission estimated that extending small-company relief to small mid-caps would ease implementation for a further 8,250 companies. This was its estimate when the change was proposed."]'::jsonb, false, '[{"title":"UK GDPR, Article 24: Responsibility of the controller","publisher":"legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/eur/2016/679/article/24","locator":"Art. 24(1)","access":"free"},{"title":"Guidance on AI and data protection: What are the accountability and governance implications of AI?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/what-are-the-accountability-and-governance-implications-of-ai/","locator":"Section ''How should we approach AI governance and risk management?'', second paragraph; section on managing trade-offs","access":"free"},{"title":"Data protection audit framework","publisher":"Information Commissioner''s Office","year":2025,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/","locator":"Opening section and ''Who can use the framework?''","access":"free"},{"title":"A pro-innovation approach to AI regulation (white paper)","publisher":"Department for Science, Innovation and Technology","year":2023,"url":"https://www.gov.uk/government/publications/ai-regulation-a-pro-innovation-approach/white-paper","locator":"Part 2, paragraph 28; Part 3, paragraph 37 (''Proportionate'')","access":"free"},{"title":"SS1/23: Model risk management principles for banks","publisher":"Prudential Regulation Authority, Bank of England","year":2023,"url":"https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/supervisory-statement/2023/ss123.pdf","locator":"Paragraphs 3.3 and 3.4 (''Proportionality''), p.9","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 11: Technical documentation","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-11","locator":"Art. 11(1), second subparagraph (marked AMENDED)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 63: Derogations for specific operators","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-63","locator":"Art. 63(1) (marked AMENDED) and 63(2)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 99: Penalties","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-99","locator":"Art. 99(1) (marked AMENDED), 99(6) and 99(6a) (marked NEW)","access":"free"},{"title":"AI Omnibus enters into force","publisher":"European Commission","year":2026,"url":"https://digital-strategy.ec.europa.eu/en/news/ai-omnibus-enters-force","locator":"Bullets ''Support for growing companies'', ''High-risk AI systems in Annex III'' and ''Simplification for SMCs''","access":"free"},{"title":"AI Act Service Desk: Frequently Asked Questions (Digital Omnibus)","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/faq","locator":"Question ''How will these changes benefit to businesses?'' (tagged Digital Omnibus)","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('3.1', '["**What it measures.** Whether the organisation knows where its AI could treat people worse because of who they are: each AI use set against the protected characteristics it could affect, with a named owner.","**Why it matters.** A model can discriminate without anyone intending it, and without holding any protected data. The Information Commission (ICO) puts it plainly: \"These ''proxy variables'' enable the model to reproduce patterns of discrimination associated with those characteristics, even if the designers did not intend this.\" Removing the sensitive fields does not remove the risk.","**The UK position.** The Equality Act 2010 protects nine characteristics. Indirect discrimination turns on effect, not motive: a practice that puts a protected group at a particular disadvantage is unlawful unless it is a proportionate means of achieving a legitimate aim. The duty sits with the employer or service provider applying the practice, and anything done by an agent with the organisation''s authority is treated as its own act, whether or not it knew. Data protection law adds a separate fairness duty: no unjustified adverse effects on individuals. The regulator has made automated decisions in recruitment a stated priority.","**What good looks like.** A documented map, refreshed when a use changes, reported to the board, independently reviewed, and consulted before purchase or deployment. Government guidance on recruitment expects an impact assessment before procurement and again before deployment.","**Reading the answer.** Awareness confined to HR is the usual weak point; pricing, lending and service triage carry the same exposure. A low answer here limits what the organisation can credibly claim about bias testing and monitoring.","**A defensible figure.** Auditing AI recruitment tools in 2024, the regulator made 296 recommendations to developers and providers; 97% were accepted and 3% partially accepted."]'::jsonb, true, '[{"title":"Equality Act 2010, section 19: Indirect discrimination","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/19","locator":"s.19(1)-(3)","access":"free"},{"title":"Equality Act 2010, section 109: Liability of employers and principals","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/109","locator":"s.109(2)-(4)","access":"free"},{"title":"Guidance on AI and data protection: What about fairness, bias and discrimination?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-fairness-in-ai/what-about-fairness-bias-and-discrimination/","locator":"Sections ''Why might an AI system lead to discrimination?'' and ''Should we just remove all sensitive data?''","access":"free"},{"title":"AI tools in recruitment: audit outcomes report","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/action-weve-taken/audits-and-overview-reports/ai-tools-in-recruitment/","locator":"pp. 3-4, 7, 12","access":"free"},{"title":"Responsible AI in Recruitment","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/publications/responsible-ai-in-recruitment-guide/responsible-ai-in-recruitment","locator":"Sections on assurance mechanisms before procurement and before deployment","access":"free"},{"title":"AI and biometrics strategy","publisher":"Information Commissioner''s Office","year":2025,"url":"https://ico.org.uk/about-the-ico/our-information/our-strategies-and-plans/artificial-intelligence-and-biometrics-strategy/","locator":"Priority on automated decision-making","access":"free"}]'::jsonb, '2026-10-05')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('3.2', '["**What it measures.** Whether data is examined for inherited unfairness before it informs decisions about people: where it came from, who is missing, and which ordinary-looking fields stand in for protected characteristics.","**Why it matters.** A system trained on past decisions repeats them. Where past lending was prejudiced against women, the Information Commission (ICO) warns, \"any model based on such training data is likely to reproduce the same pattern of discrimination.\" A thinly represented group is served worse. Those harmed are people already disadvantaged, refused again by a process that looks neutral. Deleting the sensitive column is no remedy: occupation, working hours or postcode can carry the same signal.","**The UK position.** Indirect discrimination under the Equality Act 2010 turns on effect; a biased dataset is no defence. Checking for bias often needs sensitive data. The Data Protection Act 2018 permits processing of data on race, religion, health and sexual orientation to keep equality of opportunity under review, provided it is necessary, is not used for decisions about a particular person, and a policy document is in place. Guessing is no substitute: the regulator found gender and ethnicity inferred from names too inaccurate to monitor bias.","**What good looks like.** A documented screening step covering provenance, representation and proxies, completed before the data is used; results logged and repeated as data changes; the method independently assured; the legal condition for bias-monitoring data recorded.","**Reading the answer.** Removing the sensitive fields alone is a low answer, not a high one. Buyers should ask suppliers how training data was checked.","**A defensible figure.** No defensible figure was found."]'::jsonb, false, '[{"title":"Guidance on AI and data protection: What about fairness, bias and discrimination?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-fairness-in-ai/what-about-fairness-bias-and-discrimination/","locator":"Sections ''Why might an AI system lead to discrimination?'', ''Should we just remove all sensitive data?'', ''Can we process special category data to assess and address discrimination in AI systems?''","access":"free"},{"title":"AI tools in recruitment: audit outcomes report","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/migrated/4031620/ai-in-recruitment-outcomes-report.pdf","locator":"pp. 3, 12, 18-20, 22","access":"free"},{"title":"Data Protection Act 2018, Schedule 1, paragraph 8: Equality of opportunity or treatment","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/schedule/1/paragraph/8","locator":"Sch.1 para 8(1)-(5); see also para 5 (appropriate policy document)","access":"free"},{"title":"Equality Act 2010, section 19: Indirect discrimination","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/19","locator":"s.19(1)-(2)","access":"free"},{"title":"Responsible AI in Recruitment","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/publications/responsible-ai-in-recruitment-guide/responsible-ai-in-recruitment","locator":"Sections 3.2 (during procurement), 4.1 (before deployment), Annex A (screening)","access":"free"}]'::jsonb, '2026-10-05')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('3.3', '["**What it measures.** Whether the organisation checks what its AI does to different groups: outcomes compared across groups, against thresholds set beforehand, recorded, and repeated after launch.","**Why it matters.** Without testing, the first sign of unfairness is a complaint, by which time people have already been refused a job, a loan or a service because of who they are. Testing also depends on sound group data. Auditing recruitment tools that guessed candidates'' gender and ethnicity from their names, the Information Commission (ICO) found: \"This inferred information is not accurate enough to monitor bias effectively.\"","**The UK position.** No UK statute sets a numerical test. The Equality Act 2010 asks whether a practice puts a protected group at a particular disadvantage and whether it is a proportionate means of achieving a legitimate aim. Numbers are evidence towards that question, not the answer. The regulator''s guidance, under review since the Data (Use and Access) Act 2025, expects performance to be evaluated group by group and monitored after deployment, as often as the impact warrants. Government assurance guidance calls this a bias audit and expects it repeated.","**What good looks like.** Thresholds chosen and justified in advance. Tests before launch, on a schedule and before each change. Group data collected lawfully, not guessed. Results and remedial action kept and reported to senior management.","**Reading the answer.** Common weak points: a single launch check, and tests covering only sex, ethnicity and age because nothing else is recorded. Small groups may be too few to measure.","**A defensible figure.** Many audited recruitment-tool providers used a four-fifths rule as a minimum: each group''s selection rate at least 80% of the highest group''s. It comes from United States employment guidelines, not UK law."]'::jsonb, false, '[{"title":"AI tools in recruitment: audit outcomes report","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/migrated/4031620/ai-in-recruitment-outcomes-report.pdf","locator":"pp. 3, 20-24","access":"free"},{"title":"Equality Act 2010, section 19: Indirect discrimination","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/19","locator":"s.19(2)(b) and (d)","access":"free"},{"title":"Guidance on AI and data protection: Annex A, Fairness in the AI lifecycle","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/annex-a-fairness-in-the-ai-lifecycle/","locator":"Sections ''Model evaluation'' and ''Deployment and monitoring''","access":"free"},{"title":"Guidance on AI and data protection: What about fairness, bias and discrimination?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-fairness-in-ai/what-about-fairness-bias-and-discrimination/","locator":"Sections on technical approaches to mitigating discrimination and on processing special category data to assess discrimination","access":"free"},{"title":"Responsible AI in Recruitment","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/publications/responsible-ai-in-recruitment-guide/responsible-ai-in-recruitment","locator":"Sections 3.2 (during procurement) and 4.2 (live operation)","access":"free"},{"title":"Towards a Standard for Identifying and Managing Bias in Artificial Intelligence (Special Publication 1270)","publisher":"National Institute of Standards and Technology (US)","year":2022,"url":"https://nvlpubs.nist.gov/nistpubs/SpecialPublications/NIST.SP.1270.pdf","locator":"PDF pp. 13-14 (legal context, footnote 9) and p. 41 (fairness metrics)","access":"free"}]'::jsonb, '2026-10-05')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('3.4', '["**What it measures.** Whether the organisation stops sensitive personal data from driving automated decisions about people unless a lawful exception applies, and whether that rule is enforced.","**Why it matters.** Health, ethnicity, religion, sexual orientation, trade union membership and biometric identifiers are the facts most easily turned into discrimination. When a system decides a job, a loan or a service on them with nobody looking, the person may never learn why, and the harm falls on those already most exposed.","**The UK position.** Since 5 February 2026 the UK GDPR has allowed most automated decisions, subject to safeguards. Sensitive data is the exception: \"A significant decision based entirely or partly on processing described in Article 9(1) (processing of special categories of personal data) may not be taken based solely on automated processing, unless one of the following conditions is met.\" The conditions are explicit consent, or a decision necessary for a contract or required or authorised by law, each of the last two also needing a substantial public interest condition. The regulator''s draft guidance, not yet final, applies the rule even to a small amount of such data, including inferred data.","**What good looks like.** A documented rule; every automated decision checked for sensitive data, inferred data included; technical blocks where possible; and an exceptions register, each entry recording its condition, reviewed by the board.","**Reading the answer.** The usual gap is inference. A system with no field marked health can still treat people differently on a health inference, which the regulator counts as special category data however uncertain the inference.","**A defensible figure.** The regulator''s draft guidance counts 23 substantial public interest conditions; one must apply wherever the contract or legal-authority route is used."]'::jsonb, false, '[{"title":"UK GDPR, Article 22B: Restrictions on automated decision-making","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22B","locator":"Art. 22B(1)-(4); textual amendment note F1","access":"free"},{"title":"Data (Use and Access) Act 2025, section 80: Automated decision-making","publisher":"legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/ukpga/2025/18/section/80","locator":"s.80(1); commencement notes I1, I2","access":"free"},{"title":"The Data (Use and Access) Act 2025 (Commencement No. 6 and Transitional and Saving Provisions) Regulations 2026 (S.I. 2026/82)","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/uksi/2026/82/regulation/2/made","locator":"reg. 2(j); saving in reg. 5","access":"free"},{"title":"UK GDPR, Article 9: Processing of special categories of personal data","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/9","locator":"Art. 9(1) and 9(2)(g)","access":"free"},{"title":"Automated decision-making, including profiling (draft guidance): When can we use special category data in our ADM?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/when-can-we-use-special-category-data-in-our-adm/","locator":"Sections ''What is special category data?'' and ''What are the special category data conditions for ADM?''","access":"free"},{"title":"Special category data: What is special category data?","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/lawful-basis/special-category-data/what-is-special-category-data/","locator":"Section ''What about inferences?'' (updated 9 April 2024)","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('3.5', '["**What it measures.** Whether the people who review AI-supported decisions can change them: competent to judge the output, authorised to overrule it, and able to see how it was reached.","**Why it matters.** A reviewer who passes on the system''s proposal protects no one. The person refused a job or a loan believes someone considered their case when nobody did. The regulator calls the cause automation bias: people trust the output and stop using their own judgement.","**The UK position.** Since February 2026 the UK GDPR has said \"a decision is based solely on automated processing if there is no meaningful human involvement in the taking of the decision\". The statute does not define meaningful; it requires only that the extent of profiling be weighed. The practical test is the Information Commission (ICO)''s: can the reviewer exercise real influence before the decision is applied, with the authority, discretion and competence to alter it? Access to the system''s reasoning is not in the statute; the regulator treats outputs reviewers cannot interpret as a risk that review becomes empty. Where a significant decision has no meaningful involvement, the person must be told and able to make representations, obtain human intervention and contest it.","**What good looks like.** Reviewers trained and authorised in writing to overrule; reasons and inputs visible to them; acceptance and rejection rates monitored; reviews sampled and re-checked; results fed into training and design.","**Reading the answer.** Reviewers who routinely agree and cannot show they assessed the case may be treated as absent. Reviewing only high scorers is a common gap.","**A defensible figure.** For its March 2026 recruitment report the regulator contacted 37 employers and judged 16 likely to be using automated decision-making on candidates."]'::jsonb, false, '[{"title":"Data (Use and Access) Act 2025, section 80: Automated decision-making","publisher":"legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/ukpga/2025/18/section/80","locator":"s.80(1), inserting UK GDPR Articles 22A-22D","access":"free"},{"title":"UK GDPR, Article 22A: Automated processing and significant decisions","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22A","locator":"Art. 22A(1)(a) and 22A(2)","access":"free"},{"title":"UK GDPR, Article 22C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22C","locator":"Art. 22C(2)(a)-(d); textual amendment note F1","access":"free"},{"title":"Guidance on AI and data protection: How do we ensure individual rights in our AI systems?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-individual-rights-in-our-ai-systems/","locator":"Section ''What is the role of human oversight?'' through ''What monitoring should we undertake?''","access":"free"},{"title":"Recruitment rewired: an update on the ICO''s work on the fair and responsible use of automation in recruitment","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/about-the-ico/what-we-do/recruitment-rewired/key-findings-how-are-employers-automating-their-recruitment-processes/meaningful-human-involvement/","locator":"Executive summary (parent page) and section ''Meaningful human involvement''","access":"free"},{"title":"AI tools in recruitment: audit outcomes report","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/migrated/4031620/ai-in-recruitment-outcomes-report.pdf","locator":"''Human reviews in AI'', pp. 32-34","access":"free"},{"title":"Recruitment rewired: Introduction","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/about-the-ico/what-we-do/recruitment-rewired/introduction-what-is-adm-and-why-are-we-focusing-on-it-in-recruitment/","locator":"Section ''How we''ve examined automated recruitment practices''","access":"free"}]'::jsonb, '2026-10-05')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('3.6', '["**What it measures.** Whether there is a defined point before deployment where ethical concerns are heard, and where the reviewers can require changes or refuse outright.","**Why it matters.** The people harmed by a poor AI deployment (customers scored, staff monitored, applicants filtered out) are rarely in the room when it is approved. A gate is how their interests are weighed before the harm, not after. Without power to refuse, review only records concerns about a decision already made.","**The UK position.** No UK law requires an ethics committee, but the law does supply one hard gate. Where processing of personal data is likely to result in a high risk to people, the controller must assess the impact before processing begins. If a high risk cannot be reduced, the regulator must be consulted first. Its guidance is blunt: \"You cannot go ahead with the processing until you have consulted us.\" The regulator may then limit or ban the processing. Breach of these duties can attract a fine of up to £8,700,000 or 2% of worldwide turnover, whichever is higher. That gate covers data protection only. Wider ethical questions are left to the organisation; government''s framework for public bodies accepts that sometimes the right choice is not to use a system at all.","**What good looks like.** Written criteria, a rule that in-scope uses pass through, minutes of what was weighed, board visibility, and outside input on contested calls. UNESCO''s 2021 recommendation asks states to introduce ethical impact assessment for AI.","**Reading the answer.** Ask whether the gate has ever refused or changed anything, and who can overrule it.","**A defensible figure.** On prior consultation the regulator has up to eight weeks to give written advice, extendable by six."]'::jsonb, false, '[{"title":"UK GDPR, Article 35: Data protection impact assessment","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/35","locator":"Art. 35(1), (3), (7)","access":"free"},{"title":"UK GDPR, Article 36: Prior consultation","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/36","locator":"Art. 36(1)-(2)","access":"free"},{"title":"Data protection impact assessments: Do we need to consult the ICO?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/accountability-and-governance/data-protection-impact-assessments-dpias/do-we-need-to-consult-the-ico/","locator":"Sections ''When do we need to consult the ICO?'', ''How long does it take?'' and ''What are the possible outcomes?''","access":"free"},{"title":"UK GDPR, Article 83: General conditions for imposing administrative fines","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/83","locator":"Art. 83(4)(a)","access":"free"},{"title":"Data and AI Ethics Framework","publisher":"Government Digital Service / Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/data-ethics-framework/data-and-ai-ethics-framework","locator":"Accountability principle; passage on human oversight (''the right choice might be to not use the system at all'')","access":"free"},{"title":"Recommendation on the Ethics of Artificial Intelligence","publisher":"UNESCO","year":2021,"url":"https://www.unesco.org/en/legal-affairs/recommendation-ethics-artificial-intelligence","locator":"Policy Area 1: Ethical impact assessment, paras 50-53","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('3.7', '["**What it measures.** Whether a supplier''s statement that its AI is fair is tested before the organisation relies on it: evidence asked for, read, re-checked, and backed by contract terms that give a right to look.","**Why it matters.** The people affected are applicants, customers and staff scored or filtered by a tool the organisation did not build and cannot see inside. If the tool treats a group worse, they bear the harm, and they have no dealings with the supplier. The evidence sits with the vendor; the decision sits with the buyer.","**The UK position.** The Equality Act 2010 places the duty not to discriminate on the employer and the service provider. Whether a software supplier counts as their agent is untested, so buying a tool should not be assumed to move the duty. Data protection law requires a controller to be able to demonstrate fair processing, to use only processors giving sufficient guarantees, and to hold a contract allowing audits and inspections. That audit right covers data protection compliance; a wider fairness warranty has to be negotiated.","**What good looks like.** The Information Commission (ICO) tells recruiters: \"Request test results or reports and evidence of actions AI providers have taken to address fairness, accuracy, or bias issues in AI tools or outputs.\" Government guidance adds a pilot on the organisation''s own data before deployment.","**Reading the answer.** The usual weak point is evidence requested and filed unread. A high answer needs someone able to judge the test results, and a record of what was done when the supplier last changed the model.","**A defensible figure.** Auditing providers of AI recruitment tools, the regulator made 296 recommendations; 97% were accepted in full and 3% in part."]'::jsonb, false, '[{"title":"AI tools in recruitment: audit outcomes report","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/migrated/4031620/ai-in-recruitment-outcomes-report.pdf","locator":"pp. 12, 19, 24, 40, 44-45, 47","access":"free"},{"title":"Thinking of using AI to assist recruitment? Our key data protection considerations","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/about-the-ico/media-centre/news-and-blogs/2024/11/thinking-of-using-ai-to-assist-recruitment-our-key-data-protection-considerations/","locator":"Questions 3 and 4","access":"free"},{"title":"UK GDPR, Article 28: Processor","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/28","locator":"Art. 28(1) and 28(3)(h)","access":"free"},{"title":"Equality Act 2010, section 109: Liability of employers and principals","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/109","locator":"s.109(2)-(3); read with s.29(1)-(2) and s.39(1)-(2)","access":"free"},{"title":"Responsible AI in Recruitment","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/publications/responsible-ai-in-recruitment-guide/responsible-ai-in-recruitment","locator":"Sections 3.2 (during procurement), 4.1 (before deployment), 4.2 (ongoing monitoring; iterative bias audits)","access":"free"},{"title":"Guidelines for AI procurement","publisher":"Office for Artificial Intelligence (UK government)","year":2020,"url":"https://www.gov.uk/government/publications/guidelines-for-ai-procurement/guidelines-for-ai-procurement","locator":"Sections ''Selection, evaluation and award'' and ''Contract implementation and ongoing management''","access":"free"}]'::jsonb, '2026-10-05')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('3.8', '["**What it measures.** Whether, when AI is found to have treated people unfairly, the organisation corrects the system, re-examines the decisions it influenced and puts the affected people right.","**Why it matters.** Fixing a model helps the next applicant, not the one already refused a job, a loan or a service. Left untold, that person keeps the harm and cannot use the remedies the law provides. A quiet fix leaves the cost of the error with the people least able to detect it.","**The UK position.** The 2023 white paper made contestability and redress one of five principles, but said: \"The UK’s initial non-statutory approach will not create new rights or new routes to redress at this stage.\" Redress therefore runs through existing law. For a significant decision taken solely by automated processing, the person must be given information and be able to make representations, obtain human intervention and contest it. Anyone who suffers damage from a data protection infringement has a right to compensation. Under the Equality Act, a tribunal can award compensation and recommend steps to reduce the adverse effect on the complainant. Since 19 June 2026 controllers must also respond to data protection complaints and report the outcome.","**What good looks like.** A written process covering all three steps, with time to remedy measured, repeat faults tracked, independent assessment, and a public commitment that is kept.","**Reading the answer.** The usual gap is the middle step: nobody works out who was affected. None of the provisions read requires an organisation to seek out affected people unprompted; that is a commitment the board chooses.","**A defensible figure.** A controller must acknowledge a data protection complaint within 30 days of receipt (Data Protection Act 2018, section 164A(3))."]'::jsonb, false, '[{"title":"UK GDPR, Article 22C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22C","locator":"Art. 22C(1)-(2)(a)-(d)","access":"free"},{"title":"Data (Use and Access) Act 2025, section 103: Complaints by data subjects","publisher":"legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/ukpga/2025/18/section/103","locator":"s.103(2), inserting Data Protection Act 2018 s.164A(2)-(5); commencement note I2","access":"free"},{"title":"UK GDPR, Article 82: Right to compensation and liability","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/82","locator":"Art. 82(1)-(4)","access":"free"},{"title":"Equality Act 2010, section 124: Remedies: general","publisher":"legislation.gov.uk","year":2010,"url":"https://www.legislation.gov.uk/ukpga/2010/15/section/124","locator":"s.124(2)-(7); see also s.119(4) for county court awards including injured feelings","access":"free"},{"title":"A pro-innovation approach to AI regulation (white paper)","publisher":"Department for Science, Innovation and Technology","year":2023,"url":"https://www.gov.uk/government/publications/ai-regulation-a-pro-innovation-approach/white-paper","locator":"Section 3.2.3, box ''Principle: Contestability and redress'' (after para 52)","access":"free"},{"title":"OECD AI Principles, 1.3: Transparency and explainability","publisher":"OECD","year":2024,"url":"https://oecd.ai/en/dashboards/ai-principles/P7","locator":"Principle 1.3, final bullet","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('4.1', '["**What it measures.** Whether people are told, at the point of contact, that they are dealing with an AI system and not a person, under a written standard covering every channel.","**Why it matters.** People who think a person is listening disclose more and trust more. Letting that belief stand is deception by silence, and it falls hardest on children, older people and anyone in distress. The Competition and Markets Authority puts the test simply: \"if the fact they are dealing with AI rather than a person might affect people’s decisions then you should tell them.\"","**The UK position.** No UK statute names a duty to disclose AI. The duty arises from consumer law: leaving out information the average consumer needs to take an informed decision is a misleading omission, and the business answers for its AI agent even where a supplier built it. Fines can reach £300,000 or, if higher, 10% of turnover. Transparency is one of the government''s five non-statutory AI principles. In the EU, an explicit duty has applied since 2 August 2026. It falls on the system''s provider, and the exception for obvious cases is read restrictively.","**What good looks like.** Disclosure at the first exchange, in the interface or spoken aloud, in plain words. A line in the terms and conditions is not enough. Coverage is checked across web chat, voice, messaging and email, and the wording is tested with users.","**Reading the answer.** The usual gap is the channel nobody listed. A fluent assistant handling complaints is where disclosure matters most.","**A defensible figure.** In a March 2024 survey for the UK''s AI Safety Institute, 68% agreed that a customer service chatbot should make clear whether the agent is human or artificial; 16% disagreed."]'::jsonb, true, '[{"title":"Complying with consumer law when using AI agents","publisher":"Competition and Markets Authority","year":2026,"url":"https://www.gov.uk/government/publications/complying-with-consumer-law-when-using-ai-agents/complying-with-consumer-law-when-using-ai-agents","locator":"Sections ''Tell your customers if you use an AI agent'' and ''When it comes to dealing with your customers, the same rules apply whether using AI or human agents''","access":"free"},{"title":"Digital Markets, Competition and Consumers Act 2024, section 227: Misleading omissions","publisher":"legislation.gov.uk","year":2024,"url":"https://www.legislation.gov.uk/ukpga/2024/13/section/227","locator":"s.227(1), (2) and (4); read with s.225(4)(a) and s.226(1)(b)","access":"free"},{"title":"AI Act (Regulation (EU) 2024/1689), Article 50: Transparency obligations for providers and deployers of certain AI systems","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-50","locator":"Article 50(1) and 50(5); application date from Article 113 on the same site","access":"free"},{"title":"Guidelines on the implementation of the transparency obligations for certain AI systems under Article 50 of the AI Act, C(2026) 5054 final, Annex","publisher":"European Commission","year":2026,"url":"https://digital-strategy.ec.europa.eu/en/library/guidelines-transparency-obligations-providers-and-deployers-ai-systems","locator":"Section 3: paragraphs 30, 34-40 (pp. 11-15) and 42-45 with examples (pp. 16-18)","access":"free"},{"title":"A pro-innovation approach to AI regulation (white paper)","publisher":"Department for Science, Innovation and Technology","year":2023,"url":"https://www.gov.uk/government/publications/ai-regulation-a-pro-innovation-approach/white-paper","locator":"Paragraphs 10-11; section 3.2.3, ''Principle: Appropriate transparency and explainability''","access":"free"},{"title":"Should AI systems behave like people?","publisher":"AI Security Institute (then AI Safety Institute)","year":2024,"url":"https://www.aisi.gov.uk/blog/should-ai-systems-behave-like-people","locator":"Section on transparency, first bullet; survey description above it; Figure 1 caption","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('4.2', '["**What it measures.** Whether text, images, audio and video produced by the organisation''s AI carry a mark that software can detect, and a visible label where the law requires one.","**Why it matters.** Synthetic content that passes as real deceives the person who sees it and harms the person depicted: fraud, false endorsement, words never spoken. A caption is lost when the content is copied on. The European code of practice asks providers for \"at least two layers of machine-readable marking\": signed metadata and an imperceptible watermark.","**The UK position.** There is no general UK duty. The government said in March 2026 that the UK does not regulate how AI-generated content is labelled, and proposed to work with industry. The advertising regulator says there is no blanket requirement to disclose AI in adverts, though the rules on misleading content still apply. The EU duty reaches organisations outside the Union whose systems are sold there or whose output is used there. It applies from 2 August 2026; systems already on the market have until 2 December 2026. Those who publish must disclose deepfakes, and AI-written text on matters of public interest that no editor has reviewed.","**What good looks like.** An inventory of systems that generate content; signed metadata and watermarking on their output; checks that the marks survive the organisation''s publishing process; a record of what was feasible and what was chosen.","**Reading the answer.** Visible labels alone are the common middle answer; they are not marking. A high answer should rest on test evidence, not a supplier''s assurance.","**A defensible figure.** In 2025 Ofcom tested three openly available watermarking tools against 26 types of edit; some edits, such as cropping, removed the watermark."]'::jsonb, false, '[{"title":"Code of Practice on Transparency of AI-Generated Content","publisher":"European Commission (AI Office); drafted by independent chairs","year":2026,"url":"https://ec.europa.eu/newsroom/dae/redirection/document/129555","locator":"Section 1, Measure 1.1 (p. 8); Sub-measures 1.1.1 to 1.1.3 (pp. 9-10); Measure 3.3 (pp. 17-18)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 50: Transparency obligations for providers and deployers of certain AI systems","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-50","locator":"Article 50(2) and 50(4); see also Article 2(1)(a) and (c) on the same site","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 111: AI systems already placed on the market","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-111","locator":"Article 111(4), marked NEW; with Article 113 (general application from 2 August 2026)","access":"free"},{"title":"Deepfake Defences 2: The Attribution Toolkit","publisher":"Ofcom","year":2025,"url":"https://www.ofcom.org.uk/siteassets/resources/documents/online-safety/information-for-industry/deepfake-defences-2/deepfake-defences-2---the-attribution-toolkit.pdf?v=402066","locator":"Key takeaways 5 and 8 (pp. 6-7); Box 2 (p. 14); survey findings (pp. 25-26)","access":"free"},{"title":"Report on Copyright and Artificial Intelligence","publisher":"Department for Science, Innovation and Technology and Intellectual Property Office","year":2026,"url":"https://www.gov.uk/government/publications/report-and-impact-assessment-on-copyright-and-artificial-intelligence/report-on-copyright-and-artificial-intelligence","locator":"Section E: Output transparency (Overview; Conclusions and proposals); summary under ''Labelling of AI and human-created content''","access":"free"},{"title":"Disclosure of AI in Advertising: Striking the Balance Between Creativity and Responsibility","publisher":"Advertising Standards Authority and Committee of Advertising Practice","year":2025,"url":"https://www.asa.org.uk/news/disclosure-of-ai-in-advertising-striking-the-balance-between-creativity-and-responsibility.html","locator":"Whole article (dated 29 May 2025)","access":"free"}]'::jsonb, '2026-10-02')
