insert into briefings (criterion_id, body, is_sample, sources, checked) values ('4.3', '["**What it measures.** Whether the organisation can tell a person why an AI-supported decision about them came out as it did: the factors that mattered in their case, in plain words.","**Why it matters.** Someone refused a loan or a job who gets a standard paragraph cannot tell whether the decision was wrong or what to dispute. Their right to challenge exists on paper only. The regulator''s draft guidance says of the information owed: \"This is decision-specific information about the actual outcome, rather than simply repeating information you provide in your privacy notice\".","**The UK position.** Where a significant decision is solely automated, the UK GDPR requires safeguards that include giving the person information about that decision, fully in force since February 2026. Privacy notices and replies to access requests must separately give meaningful information about the logic involved. The statute does not say how much detail is owed; the regulator''s reading is still a consultation draft. Its earlier guidance with the Alan Turing Institute, now under review, names six types of explanation and separates explaining the process from explaining the outcome.","**What good looks like.** For each kind of significant decision, an agreed explanation format completed case by case: contributing factors, data used, who to ask for a review. Explanations sampled for accuracy and tested with the people who receive them.","**Reading the answer.** Privacy-notice wording alone is the usual weak answer. An organisation that cannot see why a bought-in system decided as it did cannot explain it, yet stays responsible.","**A defensible figure.** Research for the explanation guidance used two citizens'' juries, 36 people in all; most thought explanations important in recruitment and criminal justice, less so in healthcare (interim report, pages 10 and 15)."]'::jsonb, false, '[{"title":"UK GDPR, Article 22C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22C","locator":"Art. 22C(1) and 22C(2)(a); textual amendment note F1","access":"free"},{"title":"UK GDPR, Article 15: Right of access by the data subject","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/15","locator":"Art. 15(1)(h); note F4. Same wording at Art. 13(2)(f) and Art. 14(2)(g)","access":"free"},{"title":"Automated decision-making, including profiling (draft guidance): What are the ADM safeguards?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/what-are-the-adm-safeguards/","locator":"Section ''What ''information about decisions'' do we have to provide?''","access":"free"},{"title":"Explaining decisions made with AI, Part 1: What goes into an explanation?","publisher":"Information Commissioner''s Office and The Alan Turing Institute","year":2020,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/explaining-decisions-made-with-artificial-intelligence/part-1-the-basics-of-explaining-ai/what-goes-into-an-explanation/","locator":"''At a glance'' and section ''Process-based vs outcome-based explanations''","access":"free"},{"title":"Explaining decisions made with AI, Part 3: Organisational roles and functions for explaining AI","publisher":"Information Commissioner''s Office and The Alan Turing Institute","year":2020,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/explaining-decisions-made-with-artificial-intelligence/part-3-what-explaining-ai-means-for-your-organisation/organisational-roles-and-functions-for-explaining-ai/","locator":"Section ''What if we use an AI system supplied by a third party?''","access":"free"},{"title":"Project explAIn: interim report","publisher":"Information Commissioner''s Office and The Alan Turing Institute","year":2019,"url":"https://ico.org.uk/media2/migrated/2615039/project-explain-20190603.pdf","locator":"p. 10 (jury design: 18 jurors in Manchester, 18 in Coventry); p. 15 (findings by scenario)","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('4.4', '["**What it measures.** Whether a person affected by a significant automated decision can put their side, have a person look at it again and challenge the outcome, by a route that works in practice.","**Why it matters.** Even an accurate system gets individual cases wrong, and the person affected may be the only one placed to see the error. Without a working route, someone refused credit, a job or a service carries a mistake they cannot correct, with nobody answerable to them.","**The UK position.** Since February 2026 the UK GDPR requires safeguards wherever a significant decision is taken solely by automated processing of personal data: information about the decision, and the means to make representations, obtain human intervention and contest it. The Information Commission''s (ICO) draft guidance, still a consultation draft, says of human intervention: \"You must ensure this involves a review of the decision, with the possibility that you could change it.\" The reviewer needs discretion and authority to alter the decision. Spot checks do not count, because the review must be one the person can start.","**What good looks like.** People are told how to challenge when the decision is given; one simple route covers all three steps; the reviewer sees the original data and whatever the person adds; each review is recorded; outcomes are analysed and fed back into the system.","**Reading the answer.** A general complaints line that cannot reopen the decision is the usual gap. Frequent reversals may point to a fault in the system, not in the route.","**A defensible figure.** The organisation must act on such a request within one month, extendable by two further months for complex or numerous requests (UK GDPR Article 12A)."]'::jsonb, false, '[{"title":"UK GDPR, Article 22C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22C","locator":"Art. 22C(1) and 22C(2)(b)-(d); textual amendment note F1","access":"free"},{"title":"UK GDPR, Articles 12 and 12A: time limits for acting on rights requests","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/chapter/III/section/1","locator":"Art. 12(3)-(4); Art. 12A(1), (3) and (4); textual amendment notes F4, F5, F20","access":"free"},{"title":"Automated decision-making, including profiling: What are the ADM safeguards? (draft guidance for consultation)","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/what-are-the-adm-safeguards/","locator":"Sections ''How do we enable people to make representations?'', ''What is human intervention?'', ''How do we enable people to contest decisions?'' and ''What do we do if someone exercises their rights under the ADM provisions?''","access":"free"},{"title":"Guidance on AI and data protection: How do we ensure individual rights in our AI systems?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-individual-rights-in-our-ai-systems/","locator":"Section ''What steps should we take to fulfil rights related to automated decision-making?''","access":"free"},{"title":"Explaining decisions made with AI, Part 1: What goes into an explanation?","publisher":"Information Commissioner''s Office and The Alan Turing Institute","year":2020,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/explaining-decisions-made-with-artificial-intelligence/part-1-the-basics-of-explaining-ai/what-goes-into-an-explanation/","locator":"''Challenging a decision'' paragraphs under the rationale, responsibility, data and fairness explanations","access":"free"}]'::jsonb, '2026-10-05')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('4.5', '["**What it measures.** Whether the ability to explain an AI system''s outputs is settled before the system is bought or built: written into the specification and the contract, and kept current.","**Why it matters.** A person refused a job, a loan or a service by a system nobody in the organisation can explain cannot be told why, and so cannot challenge a wrong or unfair result. The harm falls on that person, not the supplier. The regulator''s guidance is direct: \"you as the data controller have the primary responsibility for ensuring that the AI system you use is capable of producing an appropriate explanation for the decision recipient.\"","**The UK position.** Data protection law requires safeguards to be built in when the means of processing are chosen, not only afterwards. Where a significant decision is taken solely by automated means, the person must be given information about it and be able to make representations, obtain human intervention and contest it. Both duties sit with the organisation as controller. Regulator guidance, currently under review, says requirements should be specified at the procurement stage; government buyers are told to put explainability in the invitation to tender.","**What good looks like.** Explainability as a selection criterion; supplier documentation obtained before adoption and sufficient for the organisation''s own explanations; a contractual right to updates when the model changes; a recorded justification wherever an opaque model is chosen; the same standard for systems built in-house.","**Reading the answer.** The usual weak point is a tool chosen on accuracy and price, the explanation question first asked after a complaint.","**A defensible figure.** Of the widely used algorithmic techniques the regulator''s guidance lists, it classes 11 as largely interpretable and four as broadly opaque."]'::jsonb, false, '[{"title":"Explaining decisions made with AI, Part 3: Organisational roles and functions for explaining AI","publisher":"Information Commissioner''s Office and The Alan Turing Institute","year":2020,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/explaining-decisions-made-with-artificial-intelligence/part-3-what-explaining-ai-means-for-your-organisation/organisational-roles-and-functions-for-explaining-ai/","locator":"Section ''What if we use an AI system supplied by a third party?''","access":"free"},{"title":"Explaining decisions made with AI, Part 2, Task 3: Build your system to ensure you are able to extract relevant information","publisher":"Information Commissioner''s Office and The Alan Turing Institute","year":2020,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/explaining-decisions-made-with-artificial-intelligence/part-2-explaining-ai-in-practice/task-3-build/","locator":"Sections ''Select an appropriately explainable model'' and ''What types of models are we choosing between?''","access":"free"},{"title":"UK GDPR, Article 25: Data protection by design and by default","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/25","locator":"Art. 25(1)","access":"free"},{"title":"UK GDPR, Article 22C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22C","locator":"Art. 22C(1)-(2); read with Art. 22A(1)-(2)","access":"free"},{"title":"Guidance on AI and data protection: What are the accountability and governance implications of AI?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/what-are-the-accountability-and-governance-implications-of-ai/","locator":"Section ''Outsourcing and third-party AI systems''","access":"free"},{"title":"Guidelines for AI procurement","publisher":"Office for Artificial Intelligence","year":2020,"url":"https://www.gov.uk/government/publications/guidelines-for-ai-procurement/guidelines-for-ai-procurement","locator":"Top 10 considerations, no. 8 ''Avoid Black Box algorithms and vendor lock in''; section on drafting the invitation to tender","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('4.6', '["**What it measures.** Whether the organisation can describe its own AI: a complete, current record of each system: purpose, a plain summary of how it works, data used, named owner.","**Why it matters.** Every explanation given to a customer, employee or regulator draws on what the organisation knows about itself. Where that is partial, people are told things nobody has checked, and faults go uncorrected in systems nobody knows are there. The regulator''s audit framework for AI states the risk: \"Without fully understanding how information is processed, neither provider nor deployer can assure themselves that they have an effective information governance regime in place.\"","**The UK position.** No UK law requires an AI register by name. Data protection law comes closest: a controller must keep a written record of its processing of personal data, including purposes and categories of data, though not how a system works or who owns it. Central government goes further: since February 2024 departments must publish a record of each algorithmic tool that significantly influences decisions affecting the public. For listed companies, the governance code asks boards to declare whether material controls are effective, for financial years beginning from 1 January 2026.","**What good looks like.** One register covering every system, including tools staff adopted without approval, written so the owner can explain each entry aloud, reviewed on a set cycle and independently checked.","**Reading the answer.** The usual weak points are knowledge held in individuals'' heads and unapproved tools no register sees.","**A defensible figure.** The record-keeping duty applies in full at 250 or more staff; smaller organisations are exempt only where processing is occasional, poses no likely risk to people''s rights and involves no special category or criminal offence data."]'::jsonb, false, '[{"title":"UK GDPR, Article 30: Records of processing activities","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/30","locator":"Art. 30(1), (3), (4), (5)","access":"free"},{"title":"UK GDPR, Article 5: Principles relating to processing of personal data","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/5","locator":"Art. 5(2)","access":"free"},{"title":"Data protection audit framework, Artificial intelligence toolkit: Governance and accountability in AI","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/artificial-intelligence/governance-and-accountability-in-ai/","locator":"Control measure ''Information flows across the entire supply chain have been comprehensively mapped'', under ''Risk''","access":"free"},{"title":"Algorithmic Transparency Recording Standard (ATRS) Mandatory Scope and Exemptions Policy","publisher":"Government Digital Service","year":2024,"url":"https://www.gov.uk/government/publications/algorithmic-transparency-recording-standard-mandatory-scope-and-exemptions-policy/algorithmic-transparency-recording-standard-atrs-mandatory-scope-and-exemptions-policy","locator":"Sections 2 (Introduction), 3.1 (Overall scope) and 4.2","access":"free"},{"title":"UK Corporate Governance Code 2024","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/documents/6709/UK_Corporate_Governance_Code_2024_a2hmQmY.pdf","locator":"Provision 29 and footnote 9 (PDF p. 14); application paragraph in the Introduction (PDF p. 6)","access":"free"},{"title":"The hidden risks of shadow AI","publisher":"National Cyber Security Centre","year":2026,"url":"https://www.ncsc.gov.uk/blogs/the-hidden-risks-of-shadow-ai","locator":"Sections ''What is shadow AI?'' and ''What are the cyber security risks of shadow AI?''","access":"free"}]'::jsonb, '2026-10-02')
