insert into briefings (criterion_id, body, is_sample, sources, checked) values ('4.7', '["**What it measures.** Whether people are told, promptly and plainly, that a significant decision about them was made by a machine, and what they can do about it.","**Why it matters.** A person who does not know a system refused their loan, job application or claim cannot ask for a human to look again, correct a wrong fact or challenge the result. The decision stands because nobody knew to question it; those least able to push back lose most.","**The UK position.** Since 5 February 2026, where a significant decision is taken solely by automated processing of personal data, the controller must have safeguards that \"provide the data subject with information about decisions described in paragraph 1 taken in relation to the data subject\". This adds to the privacy notice, which must already disclose, in plain language, that such decision-making exists. The Information Commissioner''s Office, in draft guidance not yet final, reads the safeguard as information about the actual decision, given with the outcome, with the routes to human review and challenge. The EU AI Act separately requires deployers of certain high-risk systems to tell people they are subject to them.","**What good looks like.** A notice with each decision: that it was automated, which factors counted, and how to seek review. Coverage is counted and the wording tested with real readers.","**Reading the answer.** A line in the terms and conditions is the usual weak answer. The regulator found employers treating a privacy notice as enough and telling candidates nothing about their own decision.","**A defensible figure.** In 2025 the regulator contacted 37 employers it thought likely to be using automated recruitment tools, and concluded that 16 were likely to be making automated decisions about candidates."]'::jsonb, false, '[{"title":"UK GDPR, Article 22C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22C","locator":"Art. 22C(1) and (2)(a); note F1","access":"free"},{"title":"UK GDPR, Article 13: Information to be provided where personal data are collected from the data subject","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/13","locator":"Art. 13(1) and 13(2)(f); note F7","access":"free"},{"title":"Automated decision-making, including profiling: What are the ADM safeguards?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/what-are-the-adm-safeguards/","locator":"Section ''What ''information about decisions'' do we have to provide?''","access":"free"},{"title":"Recruitment rewired: Transparency and safeguards","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/about-the-ico/what-we-do/recruitment-rewired/key-findings-how-are-employers-automating-their-recruitment-processes/transparency-and-safeguards/","locator":"Sections ''Our findings about transparency and safeguards'' and ''Discussion''","access":"free"},{"title":"Recruitment rewired: Introduction","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/about-the-ico/what-we-do/recruitment-rewired/introduction-what-is-adm-and-why-are-we-focusing-on-it-in-recruitment/","locator":"Section ''How we''ve examined automated recruitment practices''","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 26: Obligations of deployers of high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-26","locator":"Art. 26(11)","access":"free"}]'::jsonb, '2026-10-02')
