insert into briefings (criterion_id, body, is_sample, sources, checked) values ('4.8', '["**What it measures.** Whether public statements about the organisation''s AI (marketing, bids, investor material, the annual report) are checked against what the systems really do before publication, and who signs that off.","**Why it matters.** An overstated AI claim is an untruth told to people who cannot check it. Customers pay for a capability that is not there, investors price the company on it, and people are told a human reviews decisions when none does. The harm is to their ability to choose on accurate information.","**The UK position.** No rule is specific to AI; the general law on misleading statements applies. For consumers, unfair commercial practices are prohibited, including an overall presentation likely to deceive even where each statement is true. Since 6 April 2025 the Competition and Markets Authority can itself fine up to £300,000 or, if higher, 10% of turnover. Misleading advertising to business buyers is a separate criminal offence. The advertising regulator''s advice on AI products: \"Hold evidence to back up any objective claims about what your product can do\". Issuers of traded securities must compensate investors for published statements a senior manager knew were misleading, or was reckless about.","**What good looks like.** Each claim traced to evidence before release, a named sign-off, re-checks as systems change, published corrections, and independent assurance at the top level.","**Reading the answer.** Claims about governance (audited, human-reviewed, compliant) are the easiest to disprove from the organisation''s own records. A claim true at publication can become false after a system change.","**A defensible figure.** The Advertising Standards Authority identified around 16,000 unique online adverts using AI as a marketing term between July and September 2024; 68% were for business-to-business products."]'::jsonb, false, '[{"title":"Digital Markets, Competition and Consumers Act 2024, section 226: Misleading actions","publisher":"legislation.gov.uk","year":2024,"url":"https://www.legislation.gov.uk/ukpga/2024/13/section/226","locator":"s.226(1)-(3); read with s.225(1), (3)-(4) and s.227","access":"free"},{"title":"Digital Markets, Competition and Consumers Act 2024, section 182: Final infringement notice","publisher":"legislation.gov.uk","year":2024,"url":"https://www.legislation.gov.uk/ukpga/2024/13/section/182","locator":"s.182(1)-(2), (6), (8)","access":"free"},{"title":"Regulating the Illusion of Intelligence in Ads","publisher":"Committee of Advertising Practice (ASA | CAP)","year":2026,"url":"https://www.asa.org.uk/news/regulating-the-illusion-of-intelligence-in-ads.html","locator":"Section ''Human Advice vs Machine Learning'' (CAP News, 27 Aug 2026)","access":"free"},{"title":"''AI'' as a Marketing Term: A Quantitative Review of Usage in UK Advertising","publisher":"Advertising Standards Authority","year":2024,"url":"https://asa.org.uk/static/eb77bee0-a147-49b8-81856c3c83586bf2/AI-as-a-Marketing-Term-Report.pdf","locator":"pp. 3-5","access":"free"},{"title":"The Business Protection from Misleading Marketing Regulations 2008, regulation 3","publisher":"legislation.gov.uk","year":2008,"url":"https://www.legislation.gov.uk/uksi/2008/1276/regulation/3","locator":"reg.3(1)-(4); offence at reg.6","access":"free"},{"title":"Financial Services and Markets Act 2000, Schedule 10A: Liability of issuers in connection with published information","publisher":"legislation.gov.uk","year":2000,"url":"https://www.legislation.gov.uk/ukpga/2000/8/schedule/10A","locator":"paras 1-3 (given effect by s.90A)","access":"free"}]'::jsonb, '2026-10-02')
