insert into briefings (criterion_id, body, is_sample, sources, checked) values ('5.1', '["**What it measures.** Whether the organisation has worked out, system by system and in writing, which of its decisions about people are significant and taken with no meaningful human involvement.","**Why it matters.** The legal safeguards attach only to decisions inside that boundary. Draw it wrongly and a person refused a job, a loan or a benefit by a machine is never told, never offered a human review and never given a way to contest it. The harm falls on people who cannot know a line was drawn.","**The UK position.** Since 5 February 2026 a decision is significant if it produces a legal effect or a similarly significant one, and solely automated if no human is meaningfully involved. In judging that involvement, \"a person must consider, among other things, the extent to which the decision is reached by means of profiling\". The Information Commission (ICO), in draft guidance, says the human should review every decision before it is applied, with authority to change it; spot checks are not enough. Ministers may redefine either test by regulation; none were found.","**What good looks like.** A written scoping record for each system: the decision, its effect on the person, who reviews it and how. It is linked to the AI register and reopened when the system changes.","**Reading the answer.** The usual weak answer is that a human is always involved. The regulator found most employers believed their recruitment tools only supported decisions, while managers were unlikely to look at low-scoring candidates.","**A defensible figure.** The draft guidance sets three conditions, all required: a decision about a person, a significant effect, and no meaningful human involvement."]'::jsonb, true, '[{"title":"UK GDPR, Article 22A: Automated processing and significant decisions","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22A","locator":"Art. 22A(1)(b) and 22A(2); note F1","access":"free"},{"title":"UK GDPR, Article 22D: Further provision about automated decision-making","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22D","locator":"Art. 22D(1), (2) and (5)","access":"free"},{"title":"Automated decision-making, including profiling: What does the UK GDPR say about ADM?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/what-does-the-uk-gdpr-say-about-adm/","locator":"Sections ''When do the ADM provisions apply?'', ''What is a ''significant decision''?'' and ''What is a ''solely'' automated decision?''","access":"free"},{"title":"Automated decision-making, including profiling: What else do we need to consider?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/what-else-do-we-need-to-consider/","locator":"Section ''Do we have to do a data protection impact assessment (DPIA)?''","access":"free"},{"title":"Recruitment rewired: Meaningful human involvement","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/about-the-ico/what-we-do/recruitment-rewired/key-findings-how-are-employers-automating-their-recruitment-processes/meaningful-human-involvement/","locator":"Section ''Our findings about meaningful human involvement''","access":"free"},{"title":"Recruitment rewired: Understanding how meaningful human involvement applies: use cases","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/about-the-ico/what-we-do/recruitment-rewired/understanding-how-meaningful-human-involvement-applies-use-cases/","locator":"Use cases ''tools used to provide ''fit'' scores'' and ''mandatory screening questions''","access":"free"},{"title":"Recruitment rewired: DPIAs","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/about-the-ico/what-we-do/recruitment-rewired/key-findings-how-are-employers-automating-their-recruitment-processes/dpias/","locator":"Sections ''Our findings about DPIAs'' and case study","access":"free"},{"title":"UK GDPR, Article 30: Records of processing activities","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/30","locator":"Art. 30(1), (3) and (4)","access":"free"},{"title":"Algorithmic Transparency Recording Standard (ATRS) Mandatory Scope and Exemptions Policy","publisher":"Government Digital Service","year":2024,"url":"https://www.gov.uk/government/publications/algorithmic-transparency-recording-standard-mandatory-scope-and-exemptions-policy/algorithmic-transparency-recording-standard-atrs-mandatory-scope-and-exemptions-policy","locator":"Section 4.2 ''For which tools must I complete an algorithmic transparency record?''","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Annex III: High-risk AI systems referred to in Article 6(2)","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/annex-3","locator":"Annex III, points 4(a) and 5(b)","access":"free"}]'::jsonb, '2026-10-02')
