insert into briefings (criterion_id, body, is_sample, sources, checked) values ('5.2', '["**What it measures.** Whether the four safeguards the law attaches to significant, solely automated decisions exist as working processes, each with an owner, a route, a record and a test.","**Why it matters.** A right printed in a privacy notice that nobody is resourced to answer is a broken promise to someone just refused a job, a loan or a service. The mistake stands and nobody is answerable to that person.","**The UK position.** Article 22C of the UK GDPR puts the duty on the controller, which must ensure safeguards are in place: information about the decision, and the means to make representations, obtain human intervention and contest. Article 24 requires it to be able to demonstrate compliance. On recruitment, the Information Commission (ICO) reported: \"We also didn’t see widespread evidence that candidates were able to make representations, obtain human intervention or contest decisions.\" One employer told candidates of the right to human intervention but had no method for handling a request. Its guidance, still a consultation draft, says safeguards must be applied consistently, not at discretion.","**What good looks like.** A named person or team owns each route; a recorded process covers every decision in scope; requests and reviewer overrides are logged with reasons; the process is tested on a sample of cases; results reach senior management.","**Reading the answer.** Ask to see the log. An organisation that cannot show one request and who handled it has a policy, not a safeguard. Monitoring a system''s accuracy is not human intervention.","**A defensible figure.** A breach of Article 22C falls in the higher penalty tier: up to £17,500,000 or, for an undertaking, 4% of total worldwide annual turnover, whichever is higher (UK GDPR Article 83(5))."]'::jsonb, false, '[{"title":"UK GDPR, Article 22C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22C","locator":"Art. 22C(1) and 22C(2)(a)-(d); note F1","access":"free"},{"title":"UK GDPR, Article 24: Responsibility of the controller","publisher":"legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/eur/2016/679/article/24","locator":"Art. 24(1); note F1 (Art. 24(3) amended 20 August 2025)","access":"free"},{"title":"UK GDPR, Article 83: General conditions for imposing administrative fines","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/83","locator":"Art. 83(5), point (ba); notes F8 and F10","access":"free"},{"title":"Data Protection Act 2018, section 146: Assessment notices","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/section/146","locator":"s.146(1) and (2)(a)-(k)","access":"free"},{"title":"Automated decision-making, including profiling: What are the ADM safeguards? (draft guidance for consultation)","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/what-are-the-adm-safeguards/","locator":"Sections ''What are the safeguards in the ADM provisions?'', ''What is human intervention?'' and ''How do we enable people to contest decisions?''","access":"free"},{"title":"Automated decision-making, including profiling: What else do we need to consider? (draft guidance for consultation)","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/what-else-do-we-need-to-consider/","locator":"Sections ''Do we have to do a data protection impact assessment (DPIA)?'' and ''Do we need to make any other changes to our systems?'', final paragraph","access":"free"},{"title":"Recruitment rewired: Transparency and safeguards","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/about-the-ico/what-we-do/recruitment-rewired/key-findings-how-are-employers-automating-their-recruitment-processes/transparency-and-safeguards/","locator":"Section ''Our findings about transparency and safeguards'', sub-section ''Safeguards'', including the third case study (chatbot screening interviews), and ''Expectations''","access":"free"},{"title":"Data protection audit framework, Accountability toolkit: Information rights","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/accountability/information-rights/","locator":"Final control measure but one: ''People’s rights related to automated decision-making and profiling are protected''; also the control measures on resources, logging and monitoring of requests","access":"free"},{"title":"Data protection audit framework, Artificial intelligence toolkit: Human review","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/artificial-intelligence/human-review/","locator":"First control measure, ''Ways to meet our expectations''; second control measure, ''Ways to meet our expectations'' and ''Options to consider''","access":"free"},{"title":"Guidelines on Automated individual decision-making and Profiling for the purposes of Regulation 2016/679 (WP251rev.01)","publisher":"Article 29 Data Protection Working Party (endorsed by the European Data Protection Board, 25 May 2018)","year":2018,"url":"https://ec.europa.eu/newsroom/article29/redirection/document/49826","locator":"Chapter IV, section F ''Establishing appropriate safeguards'', p.27; Annex 1 good practice recommendations, row ''Appropriate safeguards'', p.32","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('5.3', '["**What it measures.** Whether the organisation can name a valid legal ground for each use of personal data in its AI: training, the data fed in, and what the system says about people.","**Why it matters.** People whose records or images are absorbed into a model seldom know, so cannot object. Processing without a valid ground is unlawful, and the harm falls on people who never had a say.","**The UK position.** UK GDPR Article 6 lists the lawful bases; at least one must apply. The Information Commission (ICO), in guidance under review, says: \"You must break down and separate each distinct processing operation, and identify the purpose and an appropriate lawful basis for each one\". Legitimate interests requires a three-part test of purpose, necessity and balance. For training generative models on web-scraped data the regulator regards it as the only basis available, and hard to meet. Since 5 February 2026 a further basis, recognised legitimate interests, covers listed purposes such as crime prevention and emergencies; it may not support a significant decision taken solely by automated processing. Reuse that is compatible still needs its own basis.","**What good looks like.** A record per purpose showing the basis chosen before processing began, the balancing assessment where one is needed, and a fresh review whenever the purpose changes.","**Reading the answer.** Legitimate interests claimed for everything, with no assessment on file, is the usual weak answer; the regulator says it cannot be a default. A basis chosen after launch is another.","**A defensible figure.** In May 2022 the regulator fined a facial recognition company £7,552,800 for, among other failings, scraping people''s images with no lawful basis. At its last update, in December 2025, the case was still before the courts."]'::jsonb, false, '[{"title":"UK GDPR, Article 6: Lawfulness of processing","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/6","locator":"Art. 6(1)(a) to (f), 6(5) and 6(11); notes F3 and F14","access":"free"},{"title":"UK GDPR, Article 22B: Restrictions on automated decision-making","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22B","locator":"Art. 22B(4); note F1","access":"free"},{"title":"UK GDPR, Annex 1: Lawfulness of processing: recognised legitimate interests","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/annex/1","locator":"Annex 1, paras 1 to 8; note F1","access":"free"},{"title":"UK GDPR, Article 8A: Purpose limitation: further processing","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/8A","locator":"Art. 8A(2) and (3); note F1. Read with Art. 5(1)(b) and 5(3)","access":"free"},{"title":"Guidance on AI and data protection: How do we ensure lawfulness in AI?","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-lawfulness-in-ai/","locator":"Section ''What should we consider when deciding lawful bases?''; also ''How should we distinguish purposes between AI development and deployment?'' and ''Can we rely on legitimate interests?''","access":"free"},{"title":"Information Commissioner''s Office response to the consultation series on generative AI: The lawful basis for web scraping to train generative AI models","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/about-the-ico/what-we-do/our-work-on-artificial-intelligence/response-to-the-consultation-series-on-generative-ai/the-lawful-basis-for-web-scraping-to-train-generative-ai-models/","locator":"''In brief'' box and section ''Our response''","access":"free"},{"title":"Legitimate interests: What is the ''legitimate interests'' basis?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/lawful-basis/legitimate-interests/what-is-the-legitimate-interests-basis/","locator":"Section ''What is the three-part test?''","access":"free"},{"title":"A guide to lawful basis: Recognised legitimate interest","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/lawful-basis/a-guide-to-lawful-basis/recognised-legitimate-interest/","locator":"''At a glance'' and section ''When can we use recognised legitimate interest?''","access":"free"},{"title":"Opinion 28/2024 on certain data protection aspects related to the processing of personal data in the context of AI models","publisher":"European Data Protection Board","year":2024,"url":"https://www.edpb.europa.eu/system/files/2024-12/edpb_opinion_202428_ai-models_en.pdf","locator":"Paras 60 and 66; executive summary pp. 2 to 3 (three-step test; scenarios on unlawfully trained models)","access":"free"},{"title":"Monetary Penalty Notice: Clearview AI Inc","publisher":"Information Commissioner''s Office","year":2022,"url":"https://ico.org.uk/media2/migrated/4020436/clearview-ai-inc-mpn-20220518.pdf","locator":"Para 3 (amount), para 4(ii) and para 68 (p. 29) on lawful basis","access":"free"}]'::jsonb, '2026-10-02')
