insert into briefings (criterion_id, body, is_sample, sources, checked) values ('5.4', '["**What it measures.** Whether data protection impact assessments are triggered when they should be, done in depth, and acted on: findings change the design, and the assessment is revisited when the system changes.","**Why it matters.** It is where someone must write down what an AI system could do to the people whose data it uses: the applicant wrongly screened out, the teenager confiding in a chatbot, the worker tracked. Done late or thinly, those people carry risks nobody weighed.","**The UK position.** UK GDPR Article 35 requires an assessment before any processing likely to result in a high risk to people. The Data (Use and Access) Act 2025 left that duty unchanged. The Information Commission (ICO) says the great majority of AI uses will meet the trigger; a decision not to assess must be documented. In 2024 the regulator said one firm''s early assessments of an AI chatbot contained \"a cursory and higher-level risk assessment, in tabular format\", with no reasons given. The controller must also review when the risk changes. Failure can bring a fine.","**What good looks like.** Every AI use screened; assessment begun early in design; risks described for the people affected, not the organisation; each mitigation owned and checked as working; senior sign-off; review on material change.","**Reading the answer.** Ask for the assessment''s date against the go-live date, and for one design change it caused. The regulator''s audit of AI recruitment tools found some assessments completed retrospectively, and most not regularly reviewed after launch.","**A defensible figure.** In the chatbot case the regulator saw five versions. It described the first four as cursory on risk and accepted the fifth, dated 22 November 2023, almost nine months after launch on 27 February 2023."]'::jsonb, false, '[{"title":"UK GDPR, Article 35: Data protection impact assessment","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/35","locator":"Art. 35(1), (3), (7), (11)","access":"free"},{"title":"UK GDPR, Article 83: General conditions for imposing administrative fines","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/83","locator":"Art. 83(4)(a)","access":"free"},{"title":"Data protection impact assessments: What is a DPIA?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/accountability-and-governance/data-protection-impact-assessments-dpias/what-is-a-dpia/","locator":"Section ''How are DPIAs used?''","access":"free"},{"title":"Data protection impact assessments: When do we need to do a DPIA?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/accountability-and-governance/data-protection-impact-assessments-dpias/when-do-we-need-to-do-a-dpia/","locator":"Sections ''What other factors might indicate likely high risk?'' and ''What does the ICO consider likely to result in high risk?''","access":"free"},{"title":"Data protection impact assessments: How do we do a DPIA?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/accountability-and-governance/data-protection-impact-assessments-dpias/how-do-we-do-a-dpia/","locator":"Sections ''Step 7: How do we conclude our DPIA?'' and ''What happens next?''","access":"free"},{"title":"Guidance on AI and data protection: What are the accountability and governance implications of AI?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/what-are-the-accountability-and-governance-implications-of-ai/","locator":"Section ''What do we need to consider when undertaking data protection impact assessments for AI?''","access":"free"},{"title":"AI tools in recruitment: audit outcomes report","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/migrated/4031620/ai-in-recruitment-outcomes-report.pdf","locator":"''DPIAs and risk management'', pp. 34-37","access":"free"},{"title":"Decision of the Information Commissioner: Snap Inc. and Snap Group Limited","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/migrated/4029988/snap-my-ai-non-confidential-decision-21-may-2024-20240619-redacted.pdf","locator":"Paras 1-8, 28, 31, 123-124 and 153","access":"free"},{"title":"Guidelines on Data Protection Impact Assessment (DPIA) and determining whether processing is \"likely to result in a high risk\" for the purposes of Regulation 2016/679 (WP 248 rev.01)","publisher":"Article 29 Data Protection Working Party (European Commission)","year":2017,"url":"https://ec.europa.eu/newsroom/just/document.cfm?doc_id=47711","locator":"Section III.D(a), p. 14; nine criteria at pp. 9-11; Annex 2 (criteria for an acceptable DPIA)","access":"free"},{"title":"Regulation (EU) 2024/1689 (Artificial Intelligence Act), Article 27: Fundamental rights impact assessment for high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-27","locator":"Art. 27(1), (2), (4)","access":"free"}]'::jsonb, '2026-10-02')
