insert into briefings (criterion_id, body, is_sample, sources, checked) values ('5.5', '["**What it measures.** Whether the organisation knows where sensitive personal data enters its AI systems (at collection, in training data and in what a system infers) and whether each use rests on a documented lawful condition.","**Why it matters.** Health, ethnicity, religion, politics, sexual orientation and a person''s face or fingerprint are the facts most easily used to exclude or expose them. A system can infer them from ordinary data without anyone deciding it should. The harm falls on the person profiled, who is rarely told.","**The UK position.** Article 9 of the UK GDPR prohibits processing special category data unless one of ten exceptions applies. Several also need a condition in Schedule 1 to the Data Protection Act 2018, many requiring an appropriate policy document. The Information Commission (ICO) says: \"If your purpose is not covered by any of the conditions, and you cannot obtain valid explicit consent, you cannot process the special category data.\" Biometric data is caught when used to identify someone. An inference is caught where the organisation intends to draw it, or to treat someone differently because of it. Criminal offence data has separate, similar rules. The ICO''s guidance is under review.","**What good looks like.** Every sensitive data flow mapped, including training data, inferences and supplier products; a named condition and policy document for each; technical blocks; an exceptions log the board reviews.","**Reading the answer.** Deleting a labelled field is not compliance if the inference remains. Consent is weak where people cannot refuse, as at work.","**A defensible figure.** In February 2024 the ICO ordered Serco Leisure to stop using facial recognition and fingerprint scanning to record attendance: 2,283 employees across 38 facilities, with no valid condition and no appropriate policy document."]'::jsonb, false, '[{"title":"UK GDPR, Article 9: Processing of special categories of personal data","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/9","locator":"Art. 9(1), 9(2)(a)-(j), 9(5); notes F1-F19","access":"free"},{"title":"UK GDPR, Article 11A: Further provision about processing of special categories of personal data","publisher":"legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/eur/2016/679/article/11A","locator":"Art. 11A(1)-(4); note F1","access":"free"},{"title":"Data Protection Act 2018, Schedule 1, Part 4: Appropriate policy document and additional safeguards","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/schedule/1/part/4","locator":"Sch. 1 paras 38-41; read with s.10 and Sch. 1 paras 1 and 5","access":"free"},{"title":"Special category data: What are the rules on special category data?","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/lawful-basis/special-category-data/what-are-the-rules-on-special-category-data/","locator":"Sections ''What does the UK GDPR say?'', ''How do the conditions work?'', ''What does ''necessary'' mean?'', ''Do we need to do a DPIA?''","access":"free"},{"title":"Guidance on AI and data protection: How do we ensure lawfulness in AI?","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-lawfulness-in-ai/","locator":"Sections ''What about special category data and data about criminal offences?'' and ''Using AI systems to make inferences'' (page updated 28 October 2024)","access":"free"},{"title":"Biometric data guidance: Biometric recognition. How do we process biometric data lawfully?","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/lawful-basis/biometric-data-guidance-biometric-recognition/how-do-we-process-biometric-data-lawfully/","locator":"''At a glance''; sections ''Can we use consent and explicit consent?'' and ''How do we determine our lawful basis and special category condition?''","access":"free"},{"title":"Enforcement Notice: Serco Leisure Operating Limited","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/woalogoc/20240219-serco-leisure-operating-limited-en.pdf","locator":"paras 17, 26(i)-(j), 27, 34-38 (pp. 7, 11-12, 15-16); Annex 1","access":"free"},{"title":"The Information Commissioner v Clearview AI Incorporated [2025] UKUT 319 (AAC)","publisher":"Upper Tribunal (Administrative Appeals Chamber)","year":2025,"url":"https://caselaw.nationalarchives.gov.uk/ukut/aac/2025/319","locator":"Summary of decision; Decision; paras 8-9, 367","access":"free"},{"title":"The Ryder Review: Independent legal review of the governance of biometric data in England and Wales","publisher":"Ada Lovelace Institute","year":2022,"url":"https://www.adalovelaceinstitute.org/report/ryder-review-biometrics/","locator":"Chapter 2 (Executive summary and recommendations), Recommendations 1-2; Chapter 5, ''Data protection law''","access":"free"},{"title":"Opinion 28/2024 on certain data protection aspects related to the processing of personal data in the context of AI models","publisher":"European Data Protection Board","year":2024,"url":"https://www.edpb.europa.eu/system/files/2024-12/edpb_opinion_202428_ai-models_en.pdf","locator":"para 17, first bullet (p.10), with footnotes 11-13","access":"free"}]'::jsonb, '2026-10-02')
