insert into briefings (criterion_id, body, is_sample, sources, checked) values ('5.6', '["**What it measures.** Whether data fed to AI systems meets a written standard: relevant to the purpose, representative of the people decided about, accurate, and no more than the purpose requires.","**Why it matters.** Every unnecessary field can leak, be misused or tilt a decision; out-of-date records produce wrong outcomes for people. The Information Commission (ICO) is blunt: \"You must not collect personal data on the off-chance that it might be useful in the future\". The opposite failure harms too: strip out too much and a system may serve some groups worse than others.","**The UK position.** UK GDPR Article 5 requires personal data to be adequate, relevant and limited to what is necessary; accurate and, where necessary, kept up to date; and kept in identifiable form no longer than necessary. Article 25 requires that, by default, only data necessary for each purpose is processed. Adequacy cuts both ways: enough data, and no more. ICO guidance, under review since the Data (Use and Access) Act 2025, accepts that minimisation may need balancing against statistical accuracy and non-discrimination. These duties cover personal data only.","**What good looks like.** For each system, a written list of data fields allowed in and kept out, with reasons; a retention schedule with evidence of deletion; checks that data stays current and representative; quality measures tracked with alerts and passed to fairness testing.","**Reading the answer.** Cleaning data only when errors cost money scores low. Ask who decided what each system needs, and when anything was last deleted.","**A defensible figure.** The regulator''s 2024 audits of AI recruitment tools found candidate data was usually kept for one or two years after the vacancy closed (page 15); several providers meant to keep their databases indefinitely."]'::jsonb, false, '[{"title":"UK GDPR, Article 5: Principles relating to processing of personal data","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/5","locator":"Art. 5(1)(c) data minimisation, 5(1)(d) accuracy, 5(1)(e) storage limitation, 5(2) accountability","access":"free"},{"title":"UK GDPR, Article 25: Data protection by design and by default","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/25","locator":"Art. 25(1)-(2)","access":"free"},{"title":"Guidance on AI and data protection: How should we assess security and data minimisation in AI?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-should-we-assess-security-and-data-minimisation-in-ai/","locator":"Sections ''What considerations about the data minimisation principle do we need to make?'', ''How should we minimise personal data in the training stage?'', ''How should we balance data minimisation and statistical accuracy?''","access":"free"},{"title":"Guidance on AI and data protection: What do we need to know about accuracy and statistical accuracy?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/what-do-we-need-to-know-about-accuracy-and-statistical-accuracy/","locator":"Sections ''What is the difference between accuracy in data protection law and statistical accuracy in AI?'' and ''What should we do about statistical accuracy post-deployment?''","access":"free"},{"title":"AI tools in recruitment: audit outcomes report","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/media2/migrated/4031620/ai-in-recruitment-outcomes-report.pdf","locator":"pp. 13-17, ''Data minimisation and purpose limitation''","access":"free"},{"title":"Data protection audit framework, artificial intelligence toolkit: Data minimisation","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/artificial-intelligence/data-minimisation/","locator":"Three control measures: review of relevance at each stage; ongoing monitoring and testing; documented retention policy and schedule","access":"free"},{"title":"A guide to the data protection principles. Principle (c): Data minimisation","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/data-protection-principles/a-guide-to-the-data-protection-principles/data-minimisation/","locator":"''At a glance''; sections ''How do we decide what is adequate, relevant and limited?'' and ''When could we be processing inadequate personal data?''","access":"free"},{"title":"Information Commissioner''s Office response to the consultation series on generative AI: Accuracy of training data and model outputs","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/about-the-ico/what-we-do/our-work-on-artificial-intelligence/response-to-the-consultation-series-on-generative-ai/accuracy-of-training-data-and-model-outputs/","locator":"Sections ''Original call for evidence'' and ''Key points from the responses''","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Section 3.6 ''Privacy-Enhanced'', p.17; see also MAP 2.3 (p.27) and Appendix B (p.38)","access":"free"},{"title":"Operationalizing the Legal Principle of Data Minimization for Personalization","publisher":"arXiv (paper in Proceedings of the 43rd International ACM SIGIR Conference); A. J. Biega, P. Potash, H. Daumé III, F. Diaz, M. Finck","year":2020,"url":"https://arxiv.org/abs/2005.13718","locator":"Abstract","access":"free"}]'::jsonb, '2026-10-02')
