insert into briefings (criterion_id, body, is_sample, sources, checked) values ('5.7', '["**What it measures.** Whether the organisation can find, correct, delete or stop using a person''s data when they ask, including data in AI training sets, outputs, profiles and suppliers'' systems, within the legal time limit.","**Why it matters.** These rights are how a person checks what is held about them, corrects it and withdraws from uses they did not choose. If AI puts their data beyond the organisation''s reach, the right exists on paper only: the person stays profiled or wrongly described.","**The UK position.** The UK GDPR gives rights of access, rectification, erasure and objection, with no exception for AI. Since the Data (Use and Access) Act 2025, access extends to what a reasonable and proportionate search can find. Erasure and objection are not absolute, except objection to direct marketing. Guidance from the Information Commission (ICO), under review, says: \"When procuring an AI service, you must choose one which allows individual rights to be protected and enabled, in order to meet your obligations as a controller.\" The regulator has said output filters may not be enough, because they do not remove data from a model.","**What good looks like.** Rights procedures name each AI system and where its personal data sits; supplier contracts require help with requests; deletion and suppression routes are tested; turnaround and completeness are measured.","**Reading the answer.** The usual gap is a sound general process never tried against an AI system. Ask for the last request that touched one.","**A defensible figure.** No UK figure was found. In Europe, 764 controllers answered the European Data Protection Board''s 2025 coordinated action on erasure; the first recurring issue was no documented, current procedure for handling requests (report, pages 2 and 3)."]'::jsonb, false, '[{"title":"UK GDPR, Article 15: Right of access by the data subject","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/15","locator":"Art. 15(1)(h), 15(1A) and 15(3); textual amendment notes F4, F5 and F8","access":"free"},{"title":"UK GDPR, Article 17: Right to erasure (''right to be forgotten'')","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/17","locator":"Art. 17(1)(a)-(g), 17(2) and 17(3)","access":"free"},{"title":"UK GDPR, Article 21: Right to object","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/21","locator":"Art. 21(1)-(4); textual amendment note F1","access":"free"},{"title":"Guidance on AI and data protection: How do we ensure individual rights in our AI systems?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-individual-rights-in-our-ai-systems/","locator":"Sections ''How should we ensure individual rights requests for training data?'', ''How should we ensure individual rights requests for AI outputs?'' and ''How do individual rights relate to data contained in the model itself?''","access":"free"},{"title":"Response to the consultation series on generative AI: Engineering individual rights into generative AI models","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/about-the-ico/what-we-do/our-work-on-artificial-intelligence/response-to-the-consultation-series-on-generative-ai/engineering-individual-rights-into-generative-ai-models/","locator":"Section ''Our response''; also ''In brief'' and ''Key points from the responses''","access":"free"},{"title":"Right of access: How do we find and retrieve the relevant information?","publisher":"Information Commissioner''s Office","year":2025,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/right-of-access/how-do-we-find-and-retrieve-the-relevant-information/","locator":"Sections ''What efforts do we need to make to find information?'', ''What about archived information and backup records?'' and ''What about personal information in big datasets?''","access":"free"},{"title":"Data protection audit framework, artificial intelligence toolkit: Contracts and third parties","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/artificial-intelligence/contracts-and-third-parties/","locator":"List beginning ''Include terms or clauses stating that''","access":"free"},{"title":"Opinion 28/2024 on certain data protection aspects related to the processing of personal data in the context of AI models","publisher":"European Data Protection Board","year":2024,"url":"https://www.edpb.europa.eu/system/files/2024-12/edpb_opinion_202428_ai-models_en.pdf","locator":"Para. 43 (p. 16); also para. 65 (p. 21) and the lists of mitigating measures on pp. 29-30 and para. 114 (p. 32)","access":"free"},{"title":"2025 Coordinated Enforcement Action: Implementation of the right to erasure by controllers","publisher":"European Data Protection Board","year":2026,"url":"https://www.edpb.europa.eu/system/files/2026-02/edpb_cef-report_2025_right-to-erasure_en.pdf","locator":"Executive summary, pp. 2-3; section 3.1, p. 9","access":"free"},{"title":"Machine Unlearning Doesn''t Do What You Think: Lessons for Generative AI Policy and Research","publisher":"arXiv (Cooper and others; NeurIPS 2025)","year":2024,"url":"https://arxiv.org/abs/2412.06966","locator":"Abstract","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('5.8', '["**What it measures.** Whether the organisation can prove, from records made at the time, how each AI system uses personal data: scope, legal basis, risk assessment, safeguards and decisions taken.","**Why it matters.** A person refused a loan or a job by an AI system can only have that outcome checked if someone can show what was done and why. Without records, mistakes cannot be traced or put right, and nobody outside can confirm the person was treated fairly. The regulator warns: \"if you can’t show good data protection practices, it may leave you open to fines and reputational damage.\"","**The UK position.** Data protection law makes the organisation responsible for compliance and for being able to demonstrate it. The Information Commission (ICO) can require information and, since August 2025, documents, and can inspect premises and equipment. Since February 2026 it can also require a report, by a person it approves, at the organisation''s expense and, where it suspects a breach, call current or former staff and managers to answer questions. Ignoring a notice can itself be fined. Ordinary cooperation earns no reduction in a fine: the regulator treats it as required by law.","**What good looks like.** One file per system, kept current, in a known place, which someone other than its author can produce. The regulator''s auditors ask first for policies, risk registers and records of processing, then test whether practice matches.","**Reading the answer.** The usual weak point is evidence that exists but is scattered, or assembled only when a request arrives.","**A defensible figure.** An urgent information notice can require documents 24 hours after it is given; an urgent assessment notice, seven days. In 2025/26 the regulator completed 85 audits, risk reviews and follow-ups."]'::jsonb, false, '[{"title":"UK GDPR, Article 5: Principles relating to processing of personal data","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/5","locator":"Art. 5(2)","access":"free"},{"title":"Data Protection Act 2018, section 142: Information notices","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/section/142","locator":"s.142(1), (5)-(7); notes F2-F13","access":"free"},{"title":"Data Protection Act 2018, section 146: Assessment notices","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/section/146","locator":"s.146(2)(a)-(k), (3A), (8), (9), (11A); section 146A","access":"free"},{"title":"Data Protection Act 2018, section 148A: Interview notices","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/section/148A","locator":"s.148A(1)-(3), (8)","access":"free"},{"title":"Data Protection Act 2018, section 155: Penalty notices","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2018/12/section/155","locator":"s.155(1)(b)-(c), (3)(d), (3)(f); section 157(4)","access":"free"},{"title":"Data Protection Fining Guidance: Relevant aggravating or mitigating factors","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/about-the-ico/our-information/policies-and-procedures/data-protection-fining-guidance/circumstances-in-which-the-commissioner-would-consider-it-appropriate-to-issue-a-penalty-notice/relevant-aggravating-or-mitigating-factors/","locator":"Sections ''The degree of responsibility of the controller or processor'' and ''The degree of cooperation with the Commissioner''; footnotes 69-71","access":"free"},{"title":"Guide to accountability and governance","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/accountability-and-governance/guide-to-accountability-and-governance/","locator":"Sections ''Why is accountability important?'', ''What do we need to do?'' and ''What documentation should we maintain?''; checklist","access":"free"},{"title":"Data protection audit framework, Artificial intelligence toolkit: Governance and accountability in AI","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/artificial-intelligence/governance-and-accountability-in-ai/","locator":"Control measures on the privacy management framework, the DPIA, the audit programme and change management","access":"free"},{"title":"A guide to ICO audits (version 1.5)","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/media2/pyophl0h/guide-to-data-protection-audits.pdf","locator":"pp. 3-4 (executive summary, compulsory audits), p. 7 (''Document review''), p. 8","access":"free"},{"title":"Information Commissioner''s Annual Report and Financial Statements 2025/26 (HC 274)","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/media2/ybsi5n0j/ico-annual-report-202527.pdf","locator":"p. 65 (''Regulatory Assurance audits''); table p. 67; pp. 34, 59, 62-63","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('6.1', '["**What it measures.** Whether the organisation knows the ways an AI system can be attacked that ordinary software cannot, and has written down which of them apply to each system it runs.","**Why it matters.** A poisoned model or a hijacked assistant still looks as if it is working. The people harmed are those it decides about or acts for: the applicant scored by a manipulated screening tool, the customer whose records an assistant is tricked into disclosing. They cannot see the attack, and often nor can the organisation.","**The UK position.** No UK statute requires an AI threat model. The government''s voluntary Code of Practice for the Cyber Security of AI, published in January 2025, says developers and operators shall analyse threats to their systems, and that \"Threat modelling should include regular reviews and updates and address AI-specific attacks, such as data poisoning, model inversion, and membership inference.\" The National Cyber Security Centre warns that language models do not separate instructions from data, so injected instructions may never be fully prevented.","**What good looks like.** A threat model for each system, covering poisoned data, crafted inputs, injected instructions, theft of the model and leakage of what it learned. It includes systems bought from suppliers, is refreshed as new attacks are reported, and is tested by people trying to break the system.","**Reading the answer.** The weak answer is that AI is covered by the existing cyber programme. Ask to see the document, its date, and what last changed because of it.","**A defensible figure.** In a public competition reported by the AI Security Institute, participants submitted 1.8 million prompt-injection attacks against 22 AI agents; over 60,000 succeeded in making an agent break its rules."]'::jsonb, true, '[{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Principle 3, provisions 3.1, 3.1.1 and 3.2","access":"free"},{"title":"Prompt injection is not SQL injection (it may be worse)","publisher":"National Cyber Security Centre","year":2025,"url":"https://www.ncsc.gov.uk/blog-post/prompt-injection-is-not-sql-injection","locator":"Opening section; ''No data, no instructions'' and ''Developer and organisation awareness''","access":"free"},{"title":"Guidelines for secure AI system development: Secure design","publisher":"National Cyber Security Centre","year":2023,"url":"https://www.ncsc.gov.uk/collection/guidelines-secure-ai-system-development/guidelines/secure-design","locator":"Sections ''Raise staff awareness of threats and risks'' and ''Model the threats to your system''","access":"free"},{"title":"Adversarial Machine Learning: A Taxonomy and Terminology of Attacks and Mitigations (NIST AI 100-2e2025)","publisher":"National Institute of Standards and Technology","year":2025,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-2e2025.pdf","locator":"Section 4.2.5 ''Risk Management in Light of AML'', p. 60 (PDF p. 73)","access":"free"},{"title":"LLM01:2025 Prompt Injection","publisher":"OWASP Gen AI Security Project","year":2025,"url":"https://genai.owasp.org/llmrisk/llm01-prompt-injection/","locator":"Description; ''Prevention and Mitigation Strategies''","access":"free"},{"title":"Security Challenges in AI Agent Deployment: Insights from a Large Scale Public Competition","publisher":"AI Security Institute","year":2025,"url":"https://www.aisi.gov.uk/research/security-challenges-in-ai-agent-deployment-insights-from-a-large-scale-public-competition","locator":"Abstract on the AI Security Institute research page","access":"free"},{"title":"Guidance on AI and data protection: How should we assess security and data minimisation in AI?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-should-we-assess-security-and-data-minimisation-in-ai/","locator":"Sections ''What security risks does AI introduce?'' and ''What types of privacy attacks apply to AI models?''","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 15: Accuracy, robustness and cybersecurity","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-15","locator":"Art. 15(5)","access":"free"},{"title":"Impact of AI on cyber threat from now to 2027","publisher":"National Cyber Security Centre","year":2025,"url":"https://www.ncsc.gov.uk/report/impact-ai-cyber-threat-now-2027","locator":"Key judgements","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('6.2', '["**What it measures.** Whether there is a written security standard that every AI system must meet, both those the organisation builds and those it buys, and whether anyone checks that it is met.","**Why it matters.** Many organisations buy their AI rather than build it. If the supplier''s security is taken on trust, the people whose data passes through the system, and those its outputs affect, carry a risk nobody examined. They did not choose the supplier and cannot inspect it.","**The UK position.** The National Cyber Security Centre''s 2023 guidelines cover secure design, development, deployment and operation. The government''s Code of Practice of January 2025 builds on them, and an ETSI specification of April 2025 carries the same provisions. On buying, the Code says an organisation that works with an external provider \"shall undertake a due diligence assessment and should ensure that the provider is adhering to this Code of Practice\". The Code is voluntary. The binding rule is narrower: where personal data is processed, UK GDPR requires security appropriate to the risk, regularly tested. A Cyber Security and Resilience Bill is before Parliament and is not yet law.","**What good looks like.** Security requirements written into development practice and into contracts. Suppliers give evidence of testing, not assurances. Systems are tested before release and again when the model changes; consequential ones are tested independently.","**Reading the answer.** A supplier questionnaire that nobody reads is the common weak answer. Ask what was last rejected, or changed, because of a security finding.","**A defensible figure.** In a 2024 government survey of 350 UK businesses using or planning to use AI, 47% of those already using it had no cyber security practices specifically for AI."]'::jsonb, false, '[{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Principle 2, provisions 2.4 and 2.7; Principle 7; Principle 9, provisions 9.1 to 9.2.1; Terminology table","access":"free"},{"title":"Implementation Guide for the AI Cyber Security Code of Practice","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://assets.publishing.service.gov.uk/media/679cae441d14e76535afb630/Implementation_Guide_for_the_AI_Cyber_Security_Code_of_Practice.pdf","locator":"Principle 2, PDF p. 14","access":"free"},{"title":"ETSI TS 104 223 V1.1.1: Securing Artificial Intelligence (SAI); Baseline Cyber Security Requirements for AI Models and Systems","publisher":"ETSI","year":2025,"url":"https://www.etsi.org/deliver/etsi_ts/104200_104299/104223/01.01.01_60/ts_104223v010101p.pdf","locator":"Provisions 5.1.2-7, 5.2.5-2 and 5.2.5-2.1","access":"free"},{"title":"Guidelines for secure AI system development","publisher":"National Cyber Security Centre","year":2023,"url":"https://www.ncsc.gov.uk/collection/guidelines-secure-ai-system-development","locator":"Executive summary and ''About the guidelines''","access":"free"},{"title":"Guidelines for secure AI system development: Secure development","publisher":"National Cyber Security Centre","year":2023,"url":"https://www.ncsc.gov.uk/collection/guidelines-secure-ai-system-development/guidelines/secure-development","locator":"Section ''Secure your supply chain''","access":"free"},{"title":"UK GDPR, Article 32: Security of processing","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/32","locator":"Art. 32(1), in particular (1)(d)","access":"free"},{"title":"AI cyber security survey: main report","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/publications/research-on-the-cyber-security-of-ai/ai-cyber-security-survey-main-report","locator":"Executive summary","access":"free"},{"title":"Cyber Governance Code of Practice","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/cyber-governance-code-of-practice/cyber-governance-code-of-practice","locator":"Introduction (modular approach to codes of practice); Principle A (risk management), action on suppliers","access":"free"},{"title":"LLM03:2025 Supply Chain","publisher":"OWASP Gen AI Security Project","year":2025,"url":"https://genai.owasp.org/llmrisk/llm032025-supply-chain/","locator":"Description","access":"free"},{"title":"Cyber Security and Resilience Bill (collection)","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/collections/cyber-security-and-resilience-bill","locator":"Overview and Background","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('6.3', '["**What it measures.** Whether the organisation knows who can change what an AI system does (its model, prompts, training data and data pipelines), limits that to those who need it, and keeps a record of every change.","**Why it matters.** A change to a prompt or a data source can alter decisions about many people at once, with no change to any code. If nobody can say who made the change, or when, the people harmed cannot get an explanation, and the organisation cannot put it right or show it was not deliberate.","**The UK position.** No UK law is specific to AI here. The government''s voluntary Code of Practice on AI cyber security says developers and operators shall review their access controls and secure models, data and pipelines, and that developers should keep \"an audit log of changes to system prompts or other model configuration (including prompts) that affect the underlying working of the systems\". Operators shall log system and user actions. Where personal data is involved, UK GDPR requires appropriate security, and that anyone with access to the data acts only on the controller''s instructions.","**What good looks like.** Named individuals, not shared log-ins, each with no more access than the role needs. Changes to prompts, models and data sources are versioned, attributable and, for consequential systems, approved before release. Suppliers give notice of their changes. Access is reviewed on a schedule.","**Reading the answer.** Ask who last changed the system prompt, and when. A slow or uncertain answer is the finding.","**A defensible figure.** Research published by the AI Security Institute found that 250 poisoned documents were enough to plant a hidden trigger in a language model, at every model and dataset size tested."]'::jsonb, false, '[{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Provisions 2.3, 5.2, 6.1, 6.3, 7.4, 8.3 and 12.1","access":"free"},{"title":"ETSI TS 104 223 V1.1.1: Securing Artificial Intelligence (SAI); Baseline Cyber Security Requirements for AI Models and Systems","publisher":"ETSI","year":2025,"url":"https://www.etsi.org/deliver/etsi_ts/104200_104299/104223/01.01.01_60/ts_104223v010101p.pdf","locator":"Provisions 5.2.2-1, 5.2.2-3 and 5.2.4-3","access":"free"},{"title":"Guidelines for secure AI system development: Secure deployment","publisher":"National Cyber Security Centre","year":2023,"url":"https://www.ncsc.gov.uk/collection/guidelines-secure-ai-system-development/guidelines/secure-deployment","locator":"Sections ''Secure your infrastructure'' and ''Protect your model continuously''","access":"free"},{"title":"Guidelines for secure AI system development: Secure development","publisher":"National Cyber Security Centre","year":2023,"url":"https://www.ncsc.gov.uk/collection/guidelines-secure-ai-system-development/guidelines/secure-development","locator":"Section ''Identify, track and protect your assets''","access":"free"},{"title":"UK GDPR, Article 32: Security of processing","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/32","locator":"Art. 32(1)(b), 32(2) and 32(4)","access":"free"},{"title":"Cyber Essentials: Requirements for IT infrastructure v3.2","publisher":"National Cyber Security Centre","year":2025,"url":"https://www.ncsc.gov.uk/files/cyber-essentials-requirements-for-it-infrastructure-v3-2.pdf","locator":"Section 4 ''User access control'', pp. 19-20","access":"free"},{"title":"Implementation Guide for the AI Cyber Security Code of Practice","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://assets.publishing.service.gov.uk/media/679cae441d14e76535afb630/Implementation_Guide_for_the_AI_Cyber_Security_Code_of_Practice.pdf","locator":"Provision 5.4, PDF p. 27, ''Implement Strong Data Access Controls''","access":"free"},{"title":"Poisoning Attacks on LLMs Require a Near-constant Number of Poison Samples","publisher":"AI Security Institute","year":2025,"url":"https://www.aisi.gov.uk/research/poisoning-attacks-on-llms-require-a-near-constant-number-of-poison-samples","locator":"Abstract on the AI Security Institute research page","access":"free"},{"title":"LLM07:2025 System Prompt Leakage","publisher":"OWASP Gen AI Security Project","year":2025,"url":"https://genai.owasp.org/llmrisk/llm072025-system-prompt-leakage/","locator":"Description","access":"free"},{"title":"Guidance on AI and data protection: How should we assess security and data minimisation in AI?","publisher":"Information Commissioner''s Office","year":2023,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-should-we-assess-security-and-data-minimisation-in-ai/","locator":"Section ''How should we ensure training data is secure?''","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('6.4', '["**What it measures.** Whether each AI system can be stopped quickly, by people who have the authority to do it and know how, and whether that has been tried.","**Why it matters.** A system that goes wrong keeps going until someone stops it. Each further hour means more wrong decisions, disclosed data or unwanted actions, against people who have no means of stopping it themselves. Systems that act, rather than advise, do this faster.","**The UK position.** No general UK law requires an off switch for AI. One sector has such a rule: firms engaged in algorithmic trading must be able to cancel unexecuted orders immediately in an emergency. The government''s voluntary Code of Practice on AI cyber security says developers and operators shall create, test and maintain incident and recovery plans, and that operators should be able to restore a known good state. The EU AI Act will require high-risk systems to let a person \"interrupt the system through a ''stop'' button or a similar procedure that allows the system to come to a halt in a safe state\".","**What good looks like.** For each system: the conditions that trigger a stop, the roles allowed to order it, the technical means, and what the business does meanwhile. More than one person can do it. It is rehearsed and timed. Systems that take actions get a containment design before going live.","**Reading the answer.** The weak answer is that one person knows how. Ask when it was last tried and how long it took.","**A defensible figure.** The AI Security Institute, examining 177,436 publicly available tools for AI agents, found that tools which take actions rose from 27% to 65% of usage in 16 months."]'::jsonb, false, '[{"title":"Commission Delegated Regulation (EU) 2017/589, Article 12: Kill functionality","publisher":"legislation.gov.uk","year":2017,"url":"https://www.legislation.gov.uk/eur/2017/589/article/12","locator":"Art. 12(1) and (3)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 14: Human oversight","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-14","locator":"Art. 14(4)(e)","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Table 4, MANAGE 2.4, p. 32; Table 1, GOVERN 1.7, p. 23","access":"free"},{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Provisions 4.1, 4.3, 5.3, 5.3.1 and 6.5","access":"free"},{"title":"Implementation Guide for the AI Cyber Security Code of Practice","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://assets.publishing.service.gov.uk/media/679cae441d14e76535afb630/Implementation_Guide_for_the_AI_Cyber_Security_Code_of_Practice.pdf","locator":"Provision 5.3, PDF p. 26; Principle 4, PDF p. 21","access":"free"},{"title":"Guidelines for secure AI system development: Secure design","publisher":"National Cyber Security Centre","year":2023,"url":"https://www.ncsc.gov.uk/collection/guidelines-secure-ai-system-development/guidelines/secure-design","locator":"Section ''Design your system for security as well as functionality and performance''","access":"free"},{"title":"LLM06:2025 Excessive Agency","publisher":"OWASP Gen AI Security Project","year":2025,"url":"https://genai.owasp.org/llmrisk/llm062025-excessive-agency/","locator":"''Prevention and Mitigation Strategies''","access":"free"},{"title":"How are AI agents used? Evidence from 177,000 MCP tools","publisher":"AI Security Institute","year":2026,"url":"https://www.aisi.gov.uk/research/how-are-ai-agents-used-evidence-from-177-000-mcp-tools","locator":"Abstract on the AI Security Institute research page","access":"free"},{"title":"Cyber Governance Code of Practice","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/cyber-governance-code-of-practice/cyber-governance-code-of-practice","locator":"Principle D (incident planning, response and recovery)","access":"free"},{"title":"Quantifying Frontier LLM Capabilities for Container Sandbox Escape","publisher":"AI Security Institute","year":2026,"url":"https://www.aisi.gov.uk/research/quantifying-frontier-llm-capabilities-for-container-sandbox-escape","locator":"Abstract on the AI Security Institute research page","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('6.5', '["**What it measures.** Whether a failing AI system triggers the organisation''s existing incident response: named scenarios, known reporting duties, rehearsal, and lessons fed back.","**Why it matters.** A model can give wrong or unfair answers for weeks with no alarm. If nobody treats that as an incident, the people refused, overcharged or exposed are not told and not put right, and the same fault harms the next person.","**The UK position.** No UK law sets a general duty to report AI failures. Where personal data is involved, a breach must be notified to the Information Commission (ICO) within 72 hours where feasible, and to the individuals when the risk to them is high. The government''s voluntary code for AI security says \"Developers and System Operators shall create, test and maintain an AI system incident management plan and an AI system recovery plan.\" Its governance code asks boards to see the plan exercised at least annually. The EU AI Act obliges providers of high-risk systems to report serious incidents to authorities, and deployers to tell the provider first; that text is being amended.","**What good looks like.** AI failure types written into the plan; reporting duties mapped beforehand; logs preserved; an AI scenario exercised yearly; each incident reviewed and the lessons applied.","**Reading the answer.** The usual weak answer is that it would be handled like any outage. Ask when an AI scenario was last rehearsed, and what changed afterwards.","**A defensible figure.** The government''s 2025/2026 breaches survey found that 25% of UK businesses had a formal incident response plan, and 45% had none of the response measures it asked about. It covers cyber incidents generally, not AI."]'::jsonb, false, '[{"title":"UK GDPR, Article 33: Notification of a personal data breach to the Commission","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/33","locator":"Art. 33(1), (2) and (5)","access":"free"},{"title":"UK GDPR, Article 34: Communication of a personal data breach to the data subject","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/34","locator":"Art. 34(1), (3) and (4)","access":"free"},{"title":"Personal data breaches: a guide","publisher":"Information Commissioner''s Office","year":2025,"url":"https://ico.org.uk/for-organisations/report-a-breach/personal-data-breach/personal-data-breaches-a-guide/","locator":"Sections ''At a glance'', ''Checklists'' and ''What breaches do we need to notify the ICO about?''; latest update noted 20 August 2025","access":"free"},{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Principle 6, provision 6.5; also 2.3, 10.3 and 12.1","access":"free"},{"title":"Cyber Governance Code of Practice","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/cyber-governance-code-of-practice/cyber-governance-code-of-practice","locator":"Section D: Incident planning, response and recovery, Actions 1 to 4","access":"free"},{"title":"Incident management. Plan: Your cyber incident response processes","publisher":"National Cyber Security Centre","year":2019,"url":"https://www.ncsc.gov.uk/collection/incident-management/cyber-incident-response-processes","locator":"Sections ''Developing an Incident Response (IR) plan'', ''Incident Management (IM)'' and ''Playbooks and regulatory issues''; page 3 of 7, version 1.0","access":"free"},{"title":"Cyber Assessment Framework, Principle D2: Lessons learned","publisher":"National Cyber Security Centre","year":2025,"url":"https://www.ncsc.gov.uk/collection/cyber-assessment-framework/caf-objective-d/principle-d2-lessons-learned","locator":"Principle D2 statement and guidance; version 4.0, reviewed 6 August 2025","access":"free"},{"title":"Cyber security breaches survey 2025/2026","publisher":"Department for Science, Innovation and Technology and Home Office","year":2026,"url":"https://www.gov.uk/government/statistics/cyber-security-breaches-survey-20252026/cyber-security-breaches-survey-20252026","locator":"Summary, ''Incident response''; section 5.1 and Figure 5.2","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 73: Reporting of serious incidents","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-73","locator":"Art. 73(1) to (6)","access":"free"},{"title":"PS26/2: Operational incident and third party reporting","publisher":"Financial Conduct Authority","year":2026,"url":"https://www.fca.org.uk/publications/policy-statements/ps26-2-operational-incident-third-party-reporting","locator":"Summary page, sections ''Summary'' and ''Background''","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('6.6', '["**What it measures.** Whether the business can keep serving people when an AI system is unavailable, withdrawn or switched off, and how quickly it can recover.","**Why it matters.** When a system that screens claims, answers customers or schedules care stops, the people waiting bear the cost: payments delayed, questions unanswered, decisions stalled. A fallback that exists only on paper protects no one.","**The UK position.** No general law requires an AI service to be kept running. Where personal data is processed, security must include the ability to restore access to it in a timely manner after an incident. Regulated financial firms must identify their important business services, set impact tolerances and stay within them through severe but plausible disruption; they had until 31 March 2025. Since 13 July 2026 four large cloud providers have been overseen as critical third parties, but firms keep responsibility for their own third-party risk. The National Cyber Security Centre''s framework for essential services asks that \"consideration is also given to how operation of the essential function can continue in the event of technology failure or compromise\".","**What good looks like.** For each AI system the business depends on: a written manual fallback, a decision on what stops first, a recovery target, and a test that proves them. Reliance on a single supplier is named and owned.","**Reading the answer.** A supplier''s uptime guarantee answers a different question. Ask when the fallback was last run by the people who would have to run it.","**A defensible figure.** In the government''s 2025/2026 breaches survey, 33% of UK businesses had a business continuity plan that covered cyber security."]'::jsonb, false, '[{"title":"FCA Handbook, SYSC 15A: Operational resilience","publisher":"Financial Conduct Authority","year":2022,"url":"https://handbook.fca.org.uk/handbook/sysc15a","locator":"SYSC 15A.2.1R, 15A.2.5R, 15A.2.9R, 15A.4.1R, 15A.5.3R and 15A.5.8R (each dated 31/03/2022)","access":"free"},{"title":"Operational resilience","publisher":"Financial Conduct Authority","year":2026,"url":"https://www.fca.org.uk/firms/operational-resilience","locator":"Opening section and ''Operational resilience requirements for firms''; last updated 15 September 2026","access":"free"},{"title":"CrowdStrike outage: lessons for operational resilience","publisher":"Financial Conduct Authority","year":2024,"url":"https://www.fca.org.uk/firms/operational-resilience/crowdstrike-outage-lessons-operational-resilience","locator":"Sections ''Our general observations following the outage'' and ''Observations on ensuring the resilience of infrastructure''","access":"free"},{"title":"Critical third parties: strengthening UK financial services","publisher":"Financial Conduct Authority","year":2026,"url":"https://www.fca.org.uk/firms/critical-third-parties-strengthening-uk-financial-services","locator":"Sections ''What the regime means'' and ''Designated Critical Third Parties''","access":"free"},{"title":"UK GDPR, Article 32: Security of processing","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/32","locator":"Art. 32(1)(b), (c) and (d)","access":"free"},{"title":"Cyber Assessment Framework, Principle B5: Resilient networks and systems","publisher":"National Cyber Security Centre","year":2025,"url":"https://www.ncsc.gov.uk/collection/cyber-assessment-framework/caf-objective-b/principle-b5-resilient-networks-and-systems","locator":"Principle B5 description and guidance on resilience preparation; version 4.0, reviewed 6 August 2025","access":"free"},{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Principle 5, provisions 5.3 and 5.3.1; Principle 6, provision 6.5","access":"free"},{"title":"Cyber security breaches survey 2025/2026","publisher":"Department for Science, Innovation and Technology and Home Office","year":2026,"url":"https://www.gov.uk/government/statistics/cyber-security-breaches-survey-20252026/cyber-security-breaches-survey-20252026","locator":"Section 3.8 and Figure 3.9","access":"free"},{"title":"Guidelines for secure AI system development","publisher":"National Cyber Security Centre, with the US Cybersecurity and Infrastructure Security Agency and partner agencies","year":2023,"url":"https://www.ncsc.gov.uk/files/Guidelines-for-secure-AI-system-development.pdf","locator":"Section 2 ''Secure development'', ''Secure your supply chain'' (PDF page 12); section 3 ''Secure deployment'', ''Develop incident management procedures'' (PDF page 14)","access":"free"}]'::jsonb, '2026-10-02')
