insert into briefings (criterion_id, body, is_sample, sources, checked) values ('6.7', '["**What it measures.** Whether the organisation knows what its AI depends on (the supplier, the underlying model, the interfaces, the data flows) and has assessed the security of each, before adoption and after.","**Why it matters.** A deployed AI tool is usually a chain of other companies'' products. When one link is compromised or quietly changed, the harm lands on the deployer''s customers and staff: their data exposed, decisions about them altered. They did not choose the chain; the organisation that did answers for it.","**The UK position.** Under the UK GDPR a controller may use only processors that give sufficient guarantees of security. The National Cyber Security Centre''s twelve supply chain principles start here: \"Until you have a clear picture of your supply chain, it will be very hard to establish any meaningful control over it.\" The voluntary AI security code tells operators to re-run evaluations on released models they intend to use, and to tell users before a model is updated. A Bill to reform network and information systems law was introduced in November 2025; no Act was found on the date checked.","**What good looks like.** A dependency map for each system; a security assessment before adoption; reassessment when the supplier or model changes; supplier incidents tracked; contracts giving audit rights, incident notice and a way out.","**Reading the answer.** A certified vendor covers one link. Ask what the vendor itself depends on, and who would be told if the model changed.","**A defensible figure.** In the government''s 2025/2026 breaches survey, 15% of UK businesses had reviewed the risks posed by their immediate suppliers, and 6% those of their wider supply chain."]'::jsonb, false, '[{"title":"UK GDPR, Article 28: Processor","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/28","locator":"Art. 28(1), (3) and (4)","access":"free"},{"title":"Supply chain security guidance. I. Understand the risks","publisher":"National Cyber Security Centre","year":2025,"url":"https://www.ncsc.gov.uk/collection/supply-chain-security/principles-supply-chain-security/understand-the-risks","locator":"Principles 1 to 3; reviewed 22 October 2025","access":"free"},{"title":"Supply chain security guidance. III. Check your arrangements","publisher":"National Cyber Security Centre","year":2025,"url":"https://www.ncsc.gov.uk/collection/supply-chain-security/principles-supply-chain-security/check-your-arrangements","locator":"Principle 10; reviewed 22 October 2025","access":"free"},{"title":"Code of Practice for the Cyber Security of AI","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-cyber-security-code-of-practice/code-of-practice-for-the-cyber-security-of-ai","locator":"Principle 7, provisions 7.1 to 7.4; Principle 5, provision 5.1","access":"free"},{"title":"Cyber Governance Code of Practice","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/cyber-governance-code-of-practice/cyber-governance-code-of-practice","locator":"Section A: Risk management, Action 4","access":"free"},{"title":"Cyber Assessment Framework, Principle A4: Supply chain","publisher":"National Cyber Security Centre","year":2025,"url":"https://www.ncsc.gov.uk/collection/cyber-assessment-framework/caf-objective-a-managing-security-risk/principle-a4-supply-chain","locator":"Principle A4 description and guidance; version 4.0, reviewed 6 August 2025","access":"free"},{"title":"Cyber security breaches survey 2025/2026","publisher":"Department for Science, Innovation and Technology and Home Office","year":2026,"url":"https://www.gov.uk/government/statistics/cyber-security-breaches-survey-20252026/cyber-security-breaches-survey-20252026","locator":"Section 3.10 and Figure 3.13","access":"free"},{"title":"Cyber Security and Resilience (Network and Information Systems) Bill","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/collections/cyber-security-and-resilience-bill","locator":"Sections ''Overview'' and ''Latest''; page last updated 18 November 2025","access":"free"},{"title":"A pro-innovation approach to AI regulation: government response","publisher":"Department for Science, Innovation and Technology","year":2024,"url":"https://www.gov.uk/government/consultations/ai-regulation-a-pro-innovation-approach-policy-proposals/outcome/a-pro-innovation-approach-to-ai-regulation-government-response","locator":"Section 5.2, Box 2 and section 5.2.1 (case study on liability across the supply chain)","access":"free"},{"title":"The NIST Cybersecurity Framework (CSF) 2.0","publisher":"National Institute of Standards and Technology","year":2024,"url":"https://nvlpubs.nist.gov/nistpubs/CSWP/NIST.CSWP.29.pdf","locator":"Appendix A, GOVERN function, category GV.SC (GV.SC-01 to GV.SC-10), PDF pages 22 to 23","access":"free"}]'::jsonb, '2026-10-02')
