insert into briefings (criterion_id, body, is_sample, sources, checked) values ('7.1', '["**What it measures.** Whether the people who use AI for the organisation, employees and contractors alike, know enough to use it safely, and whether records show it.","**Why it matters.** Untrained staff paste confidential or personal information into public tools, accept wrong output and pass it on. Customers and the public are affected by work nobody checked; staff are blamed for errors they were never equipped to catch.","**The UK position.** No UK statute sets a general AI literacy duty. Organisations within the scope of the EU AI Act have, since February 2025, had to take measures to support the AI literacy of their staff and of others who operate or use AI on their behalf. The 2026 amendment added: \"This obligation does not require providers or deployers to guarantee any specific level of AI literacy of any individual.\" National authorities have been able to enforce it since August 2026. The European Commission says there is no duty to measure employees'' knowledge, but that relying on the instructions for use is not enough. Acas advises that staff may need training and that AI output should be checked for accuracy, tone and bias.","**What good looks like.** Training matched to role and tool, covering contractors; records of who was trained, on what and when; content refreshed when tools change; competence tested, not attendance counted.","**Reading the answer.** One recorded webinar, with no list of who watched, is the weak answer. So is a programme that stops at employees.","**A defensible figure.** In a government-commissioned survey of 801 UK employers, carried out in 2024 and published in January 2026, 11% said staff had undertaken AI training in the previous 12 months."]'::jsonb, true, '[{"title":"Regulation (EU) 2024/1689 (AI Act), Article 4: AI literacy","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-4","locator":"Art. 4(1)-(3), paragraphs marked ''AMENDED''","access":"free"},{"title":"Timeline for the Implementation of the EU AI Act","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/timeline/timeline-implementation-eu-ai-act","locator":"Entries for 02 Feb 2025 and 02 Aug 2026","access":"free"},{"title":"AI Literacy - Questions & Answers","publisher":"European Commission","year":2026,"url":"https://digital-strategy.ec.europa.eu/en/faqs/ai-literacy-questions-answers","locator":"Answers on measuring knowledge, on whether training is mandatory, on ''other persons'', and on enforcement","access":"free"},{"title":"AI skills for life and work: employer survey findings","publisher":"Department for Science, Innovation and Technology (research by Ipsos)","year":2026,"url":"https://www.gov.uk/government/publications/ai-skills-for-life-and-work-employer-survey-findings/ai-skills-for-life-and-work-employer-survey-findings--2","locator":"Key findings; section 5, Figure 5.6; methodology (sample size 801, fieldwork 19 March to 7 June 2024)","access":"free"},{"title":"Research evidence, analysis and methodology: What works for AI upskilling in the UK","publisher":"Skills England (author: Dr Nisreen Ameen, Royal Holloway, University of London)","year":2026,"url":"https://www.gov.uk/government/publications/skills-for-ai-what-works-for-ai-upskilling-in-the-uk/research-evidence-analysis-and-methodology-what-works-for-ai-upskilling-in-the-uk","locator":"Executive summary and methodology","access":"free"},{"title":"One third of employers think AI will increase productivity","publisher":"Acas","year":2025,"url":"https://www.acas.org.uk/one-third-of-employers-think-ai-will-increase-productivity","locator":"''Some top tips for employers from Acas on the use of AI at work''","access":"free"},{"title":"Artificial Intelligence Playbook for the UK Government","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/ai-playbook-for-the-uk-government/artificial-intelligence-playbook-for-the-uk-government-html","locator":"Principle 9: You have the skills and expertise needed to implement and use AI solutions","access":"free"},{"title":"AI Opportunities Action Plan","publisher":"Department for Science, Innovation and Technology","year":2025,"url":"https://www.gov.uk/government/publications/ai-opportunities-action-plan/ai-opportunities-action-plan","locator":"Recommendations 14 to 19 (skills)","access":"free"},{"title":"Explaining decisions made with AI, Part 2, Task 5: Prepare implementers to deploy your AI system","publisher":"Information Commissioner''s Office and The Alan Turing Institute","year":2024,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/explaining-decisions-made-with-artificial-intelligence/part-2-explaining-ai-in-practice/task-5-prepare/","locator":"Introduction and ''Educate implementers about the strengths and limitations of AI decision-support systems''","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0)","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Table 1, GOVERN 2.2","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('7.2', '["**What it measures.** Whether those assigned to oversee AI systems can do the job: trained on the system, given time for each case, and free to overrule it.","**Why it matters.** An overseer with no training, a heavy caseload or a manager who frowns on overrides approves what the system proposes. People affected believe someone checked their case; the overseer carries blame for outcomes they could not change.","**The UK position.** UK data protection law turns on whether human involvement in a significant decision is meaningful, but says little about the person. The Information Commission (ICO), in guidance now under review, says reviewers need authority to override and confidence they will not be penalised, adding: \"This authority and confidence cannot be created by policies and training alone: a supportive organisational culture is also crucial\". Its audit toolkit expects a manageable caseload and a log of overrides with reasons. Its draft guidance on automated decisions, still in consultation, expects reviewers trained to understand the system''s logic, outputs, limitations and risks. The EU AI Act requires deployers of high-risk systems to assign oversight to people with the competence, training, authority and support needed; the European Commission''s published text applies this to listed high-risk uses from 2 December 2027.","**What good looks like.** Named overseers with system-specific training, refreshed on change; caseloads that allow attention to each case; written authority to overrule; override rates and sampled re-reviews reported.","**Reading the answer.** A name on a chart is the weak answer. Ask how many cases a reviewer handles daily, and when anyone last overruled the system.","**A defensible figure.** A 2022 peer-reviewed study surveyed 41 policies requiring human oversight of government algorithms and found evidence that people cannot perform the oversight expected."]'::jsonb, false, '[{"title":"Guidance on AI and data protection: How do we ensure individual rights in our AI systems?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-individual-rights-in-our-ai-systems/","locator":"Section ''What is the role of human oversight?'', subsection ''How should we train our staff to address these risks?''","access":"free"},{"title":"Data protection audit framework, Artificial intelligence toolkit: Human review","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/artificial-intelligence/human-review/","locator":"First control measure and its ''ways to meet our expectations'' list","access":"free"},{"title":"Automated decision-making, including profiling: What does the UK GDPR say about ADM?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/automated-decision-making/what-does-the-uk-gdpr-say-about-adm/","locator":"Section ''What is a ''solely'' automated decision?'', list of criteria for meaningful human involvement","access":"free"},{"title":"Explaining decisions made with AI, Part 2, Task 5: Prepare implementers to deploy your AI system","publisher":"Information Commissioner''s Office and The Alan Turing Institute","year":2024,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/explaining-decisions-made-with-artificial-intelligence/part-2-explaining-ai-in-practice/task-5-prepare/","locator":"''At a glance'' and the passage on decision-automation bias","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 26: Obligations of deployers of high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-26","locator":"Art. 26(2) and 26(3)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 113: Entry into force and application","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-113","locator":"Art. 113, third paragraph, point (c)(i), marked ''AMENDED''","access":"free"},{"title":"AI Literacy - Questions & Answers","publisher":"European Commission","year":2026,"url":"https://digital-strategy.ec.europa.eu/en/faqs/ai-literacy-questions-answers","locator":"Answer to ''Is an AI training mandatory for article 4 of the AI Act or are other AI literacy initiatives also allowed?''","access":"free"},{"title":"The flaws of policies requiring human oversight of government algorithms","publisher":"Ben Green, Computer Law & Security Review 45 (author''s copy on arXiv)","year":2022,"url":"https://arxiv.org/abs/2109.05067","locator":"Abstract","access":"free"},{"title":"On the Quest for Effective Human Oversight: Legal, Philosophical, and Technical Perspectives","publisher":"Sarah Sterz and others, ACM Conference on Fairness, Accountability, and Transparency 2024 (authors'' copy on arXiv)","year":2024,"url":"https://arxiv.org/abs/2404.04059","locator":"Abstract","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0)","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Table 2, MAP 3.4; Table 1, GOVERN 3.2","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('7.3', '["**What it measures.** Whether systems are set up so a person can step in: a point to intervene before an output takes effect, reasons on screen, time to act and a way to stop.","**Why it matters.** When a screen shows a conclusion without reasons, and agreeing takes one click while disagreeing takes a form, people agree. The harm falls on people whose cases needed a second look, and on staff held responsible for decisions the design made.","**The UK position.** The UK GDPR requires safeguards to be built into processing when its means are chosen, and anyone subject to a significant, solely automated decision must be able to obtain human intervention. The Information Commission (ICO), in guidance now under review, says controls against automation bias belong in scoping and design, not only in training: \"Those in charge of designing the front-end interface of an AI system must understand the needs, thought processes, and behaviours of human reviewers and allow them to effectively intervene.\" It suggests a confidence score beside each output and testing options with reviewers early. The EU AI Act requires high-risk systems to be designed so that people can oversee, override and interrupt them; on the European Commission''s published timetable that duty does not yet apply.","**What good looks like.** A deployment standard: defined intervention points, reasons shown at decision time, overriding as easy as approving, a fall-back to manual working. Interventions are counted, designs tested with reviewers, suppliers held to the standard.","**Reading the answer.** A claim that staff can always override is weak if nobody ever has. Ask to see the reviewer''s screen and last quarter''s interventions.","**A defensible figure.** No defensible figure was found."]'::jsonb, false, '[{"title":"Guidance on AI and data protection: How do we ensure individual rights in our AI systems?","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/artificial-intelligence/guidance-on-ai-and-data-protection/how-do-we-ensure-individual-rights-in-our-ai-systems/","locator":"Section ''What is the role of human oversight?'', subsections ''How can we address risks of automation bias?'' and ''How can we address risks of interpretability?''","access":"free"},{"title":"UK GDPR, Article 25: Data protection by design and by default","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/25","locator":"Art. 25(1)","access":"free"},{"title":"UK GDPR, Article 22C: Safeguards for automated decision-making","publisher":"legislation.gov.uk","year":2026,"url":"https://www.legislation.gov.uk/eur/2016/679/article/22C","locator":"Art. 22C(2)(c)","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 14: Human oversight","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-14","locator":"Art. 14(1), 14(3) and 14(4)(a)-(e)","access":"free"},{"title":"Timeline for the Implementation of the EU AI Act","publisher":"European Commission, AI Act Service Desk","year":2026,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/timeline/timeline-implementation-eu-ai-act","locator":"Entry for 02 Dec 2027","access":"free"},{"title":"Data protection audit framework, Artificial intelligence toolkit: Human review","publisher":"Information Commissioner''s Office","year":2024,"url":"https://ico.org.uk/for-organisations/advice-and-services/audits/data-protection-audit-framework/toolkits/artificial-intelligence/human-review/","locator":"First control measure, list of ways to meet expectations (fall back and hybrid working)","access":"free"},{"title":"Artificial Intelligence Playbook for the UK Government","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/ai-playbook-for-the-uk-government/artificial-intelligence-playbook-for-the-uk-government-html","locator":"Principle 4: You have meaningful human control at the right stages","access":"free"},{"title":"Ethics, Transparency and Accountability Framework for Automated Decision-Making","publisher":"Cabinet Office","year":2023,"url":"https://www.gov.uk/government/publications/ethics-transparency-and-accountability-framework-for-automated-decision-making/ethics-transparency-and-accountability-framework-for-automated-decision-making","locator":"Section on explainability and human intervention","access":"free"},{"title":"Automation Bias in the AI Act: On the Legal Implications of Attempting to De-Bias Human Oversight of AI","publisher":"Johann Laux and Hannah Ruschemeier (authors'' copy on arXiv)","year":2025,"url":"https://arxiv.org/abs/2502.10036","locator":"Abstract","access":"free"},{"title":"Artificial Intelligence Risk Management Framework (AI RMF 1.0)","publisher":"National Institute of Standards and Technology","year":2023,"url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-1.pdf","locator":"Table 2, MAP 3.5","access":"free"}]'::jsonb, '2026-10-02')
