insert into briefings (criterion_id, body, is_sample, sources, checked) values ('7.4', '["**What it measures.** Whether the effect on jobs is assessed in writing before the board decides to adopt AI that changes work, and whether the board''s consideration is minuted.","**Why it matters.** People whose tasks, pay or posts will change tend to learn last. An assessment made beforehand lets redeployment, retraining or redesign be weighed while they are still options. Made afterwards, it is an explanation, not a safeguard.","**The UK position.** Directors must act to promote the success of the company and, in doing so, have regard among other matters to \"the interests of the company''s employees\". Companies must record minutes of directors'' meetings. Larger companies must publish a statement of how directors had regard to those matters, and the UK Corporate Governance Code asks boards to describe how they were considered in board discussions and decision-making. No UK law requires a workforce impact assessment for AI by that name, and the duty is owed to the company, not to staff. Redundancies proposed on a sufficient scale trigger collective consultation. Acas advises consulting workers and their representatives on introducing AI, and notes that expecting roles to use it could change terms and conditions.","**What good looks like.** A dated assessment before approval: roles touched, tasks removed and added, what happens to the people, transition costs, alternatives considered. The board''s discussion is minuted. Predicted effects are later compared with actual ones.","**Reading the answer.** Papers dated after the decision are the weak answer. So is an assessment that never mentions job losses.","**A defensible figure.** In the CIPD''s autumn 2025 survey of 2,019 UK employers, 17% expected the use of AI tools to reduce their headcount in the next 12 months."]'::jsonb, false, '[{"title":"Companies Act 2006, section 172: Duty to promote the success of the company","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/172","locator":"s.172(1)(a) and (b)","access":"free"},{"title":"Companies Act 2006, section 414CZA: Section 172(1) statement","publisher":"legislation.gov.uk","year":2018,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/414CZA","locator":"s.414CZA(1) and (2)","access":"free"},{"title":"Companies Act 2006, section 248: Minutes of directors'' meetings","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/248","locator":"s.248(1)-(3)","access":"free"},{"title":"UK Corporate Governance Code 2024","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/documents/6709/UK_Corporate_Governance_Code_2024_a2hmQmY.pdf","locator":"Section 1, Principle E and Provision 5 (page 7)","access":"free"},{"title":"Trade Union and Labour Relations (Consolidation) Act 1992, section 188: Duty of employer to consult representatives","publisher":"legislation.gov.uk","year":1992,"url":"https://www.legislation.gov.uk/ukpga/1992/52/section/188","locator":"s.188(1), (1A) and (4)","access":"free"},{"title":"UK GDPR, Article 35: Data protection impact assessment","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/35","locator":"Art. 35(1) and 35(9)","access":"free"},{"title":"1 in 4 workers worry that AI will lead to job losses","publisher":"Acas","year":2025,"url":"https://www.acas.org.uk/1-in-4-workers-worry-that-ai-will-lead-to-job-losses","locator":"''Some top tips for employers from Acas on the use of AI at work''","access":"free"},{"title":"Labour Market Outlook: Autumn 2025","publisher":"CIPD","year":2025,"url":"https://www.cipd.org/globalassets/media/knowledge/knowledge-hub/reports/2025-pdfs/9024-lmo-autumn-2025-report-web.pdf","locator":"Key points (page 5) and section on artificial intelligence (page 16 onwards)","access":"free"},{"title":"Generative AI and Jobs: A Refined Global Index of Occupational Exposure (ILO Working Paper 140)","publisher":"International Labour Organization","year":2025,"url":"https://webapps.ilo.org/static/english/intserv/working-papers/wp140/index.html","locator":"Abstract and Conclusion","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 26: Obligations of deployers of high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-26","locator":"Art. 26(7)","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('7.5', '["**What it measures.** Whether the people who will work with an AI system, or be managed by it, are told before it starts, and whether what they say can still change it.","**Why it matters.** A system that allocates shifts, scores performance or watches activity alters working lives. If it arrives unannounced, workers cannot ask how it judges them, warn where it will go wrong, or object. The harm is to dignity and fair treatment, and it falls on those with least say.","**The UK position.** No UK statute requires consultation on AI as such. Employers must consult employees or their safety representatives in good time on \"the health and safety consequences for those employees of the introduction (including the planning thereof) of new technologies into the workplace\". Where the statutory information and consultation provisions apply, representatives must be consulted on decisions likely to bring substantial changes in work organisation. Data protection law tells a controller assessing high-risk processing to seek, where appropriate, the views of the people affected, and the Information Commission (ICO) expects employers planning monitoring to seek and record workers'' views. The EU AI Act goes further where it applies: employers must inform workers and their representatives before a high-risk system is used at work.","**What good looks like.** Representatives and affected staff briefed before the decision is final; their comments recorded, answered and visibly acted on.","**Reading the answer.** An announcement at launch is the usual weak answer. Ask what changed because of what staff said.","**A defensible figure.** The general right to be informed and consulted covers only undertakings with at least 50 employees and, unless the employer acts first, only once 2% of them, and no fewer than 15, have asked."]'::jsonb, false, '[{"title":"The Health and Safety (Consultation with Employees) Regulations 1996, regulation 3: Duty of employer to consult","publisher":"legislation.gov.uk","year":1996,"url":"https://www.legislation.gov.uk/uksi/1996/1513/regulation/3","locator":"Reg. 3, opening words and (e)","access":"free"},{"title":"The Safety Representatives and Safety Committees Regulations 1977, regulation 4A: Employer''s duty to consult and provide facilities and assistance","publisher":"legislation.gov.uk","year":1977,"url":"https://www.legislation.gov.uk/uksi/1977/500/regulation/4A","locator":"Reg. 4A(1), opening words and (e)","access":"free"},{"title":"The Information and Consultation of Employees Regulations 2004, regulation 20: Standard information and consultation provisions","publisher":"legislation.gov.uk","year":2004,"url":"https://www.legislation.gov.uk/uksi/2004/3426/regulation/20","locator":"Reg. 20(1)(c), (2), (3) and (4)","access":"free"},{"title":"The Information and Consultation of Employees Regulations 2004, regulation 7: Employee request to negotiate an agreement","publisher":"legislation.gov.uk","year":2004,"url":"https://www.legislation.gov.uk/uksi/2004/3426/regulation/7","locator":"Reg. 7(2) and (3); Schedule 1 for the 50-employee threshold","access":"free"},{"title":"UK GDPR, Article 35: Data protection impact assessment","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/35","locator":"Art. 35(9)","access":"free"},{"title":"Employment practices and data protection: monitoring workers. Data protection and monitoring workers","publisher":"Information Commissioner''s Office","year":2026,"url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/employment/monitoring-workers/data-protection-and-monitoring-workers/","locator":"Section ''Should we discuss the introduction of monitoring with our workers?''","access":"free"},{"title":"Regulation (EU) 2024/1689 (AI Act), Article 26: Obligations of deployers of high-risk AI systems","publisher":"European Commission, AI Act Service Desk","year":2024,"url":"https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-26","locator":"Art. 26(7)","access":"free"},{"title":"UK Corporate Governance Code 2024","publisher":"Financial Reporting Council","year":2024,"url":"https://www.frc.org.uk/documents/6709/UK_Corporate_Governance_Code_2024_a2hmQmY.pdf","locator":"Section 1, Provision 5 (PDF page 8)","access":"free"},{"title":"Employment Rights Act 2025, section 29: Collective redundancy: extended application of requirements","publisher":"legislation.gov.uk","year":2025,"url":"https://www.legislation.gov.uk/ukpga/2025/36/section/29","locator":"s.29(2)","access":"free"},{"title":"My boss the algorithm: an ethical look at algorithms in the workplace","publisher":"Acas","year":2020,"url":"https://www.acas.org.uk/research-and-commentary/my-boss-the-algorithm-an-ethical-look-at-algorithms-in-the-workplace/paper","locator":"Executive summary; section ''Involving the workforce''","access":"free"}]'::jsonb, '2026-10-02')
