insert into briefings (criterion_id, body, is_sample, sources, checked) values ('7.6', '["**What it measures.** Whether the default, when AI changes a job, is to redesign the work around people, and whether success is measured by output and quality instead of posts removed.","**Why it matters.** The choice decides who gains. One economist puts it this way: \"when AI is focused on augmenting humans rather than mimicking them, then humans retain the power to insist on a share of the value created\". Where the aim is replacement, workers lose income and bargaining power, and the organisation loses the judgement it needs to check the machine. Field evidence from customer support found that AI used to assist raised productivity, most of all for the least experienced.","**The UK position.** No UK law requires augmentation. Directors must have regard to the interests of employees and to long-term consequences when promoting the company''s success. Where collective redundancies are proposed, the employer must consult representatives on ways of avoiding the dismissals and reducing their number, with a view to reaching agreement. Official statistics show that most businesses using AI report no change in headcount so far.","**What good looks like.** A written default of redesign; any departure justified case by case; managers'' targets set on throughput and quality; results reported to the board like any other strategy.","**Reading the answer.** Listen for the double message: augmentation in the staff briefing, headcount savings in the business case. Ask which measure managers are rewarded on.","**A defensible figure.** In the Office for National Statistics survey published in July 2026, just under 7% of medium-sized businesses using AI reported that it had reduced their headcount, the highest of any size band; most businesses reported no change."]'::jsonb, false, '[{"title":"Trade Union and Labour Relations (Consolidation) Act 1992, section 188: Duty of employer to consult representatives","publisher":"legislation.gov.uk","year":1992,"url":"https://www.legislation.gov.uk/ukpga/1992/52/section/188","locator":"s.188(1), (1A) and (2); notes F2, F4","access":"free"},{"title":"Companies Act 2006, section 172: Duty to promote the success of the company","publisher":"legislation.gov.uk","year":2006,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/172","locator":"s.172(1)(a) and (b)","access":"free"},{"title":"Artificial intelligence in UK businesses: 2023 to 2026","publisher":"Office for National Statistics","year":2026,"url":"https://www.ons.gov.uk/businessindustryandtrade/business/businessservices/articles/artificialintelligenceinukbusinesses/2023to2026","locator":"Section ''Labour market effects'' and Figure 7","access":"free"},{"title":"Assessment of AI capabilities and the impact on the UK labour market","publisher":"Department for Science, Innovation and Technology and AI Security Institute","year":2026,"url":"https://www.gov.uk/government/publications/assessment-of-ai-capabilities-and-the-impact-on-the-uk-labour-market/assessment-of-ai-capabilities-and-the-impact-on-the-uk-labour-market","locator":"Figure 2 and the paragraph above it","access":"free"},{"title":"Generative AI at Work","publisher":"Erik Brynjolfsson, Danielle Li and Lindsey Raymond (arXiv preprint 2304.11771)","year":2024,"url":"https://arxiv.org/pdf/2304.11771","locator":"Abstract, page 1","access":"free"},{"title":"Experimental Evidence on the Productivity Effects of Generative Artificial Intelligence","publisher":"Shakked Noy and Whitney Zhang, MIT (working paper)","year":2023,"url":"https://economics.mit.edu/sites/default/files/inline-files/Noy_Zhang_1.pdf","locator":"Abstract, page 1","access":"free"},{"title":"The Turing Trap: The Promise & Peril of Human-Like Artificial Intelligence","publisher":"Erik Brynjolfsson, Stanford Digital Economy Lab (arXiv preprint 2201.04200)","year":2022,"url":"https://arxiv.org/pdf/2201.04200","locator":"Abstract, page 1","access":"free"},{"title":"Generative AI and Jobs: A global analysis of potential effects on job quantity and quality (ILO Working Paper 96)","publisher":"International Labour Organization","year":2023,"url":"https://www.ilo.org/sites/default/files/wcmsp5/groups/public/@dgreports/@inst/documents/publication/wcms_890761.pdf","locator":"Abstract (PDF page 4)","access":"free"},{"title":"The Future of Jobs Report 2025","publisher":"World Economic Forum","year":2025,"url":"https://reports.weforum.org/docs/WEF_Future_of_Jobs_Report_2025.pdf","locator":"Key findings, page 6; chapter 2, ''The shifting human-machine frontier: automation versus augmentation''","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('7.7', '["**What it measures.** Whether staff know which AI tools they may use and for what, and whether the organisation finds out about the tools it never approved.","**Why it matters.** People paste customer records, staff files and confidential plans into free tools nobody has assessed. The individuals whose information it is never agreed to that and will never know. The organisation cannot protect what it cannot see.","**The UK position.** No law names shadow AI. Data protection law requires a controller to take steps so that anyone acting under its authority handles personal data only on its instructions, and to pass personal data to an outside service only under a binding contract. The National Cyber Security Centre treats unapproved AI as a form of shadow IT. It says such use is rarely malicious and usually shows that approved tools fall short, and it warns: \"If you blame or punish staff, their peers will be reluctant to tell you about their own unsanctioned practices\". It advises a simple, quick process for requests and tells users not to put sensitive information into public AI tools. Government research found that very few businesses had any internal policy on AI.","**What good looks like.** A short policy written for staff: approved tools, information that must never be entered, a fast route to request something new. Unapproved use found by asking without blame and by technical monitoring, and tracked over time.","**Reading the answer.** A policy nobody has read, backed by a slow approval queue, is the usual weak answer. A ban alone hides the problem.","**A defensible figure.** In a 2025 survey across 47 countries, 70% of employees who use AI at work said they use free, publicly available tools."]'::jsonb, false, '[{"title":"Shadow IT","publisher":"National Cyber Security Centre","year":2023,"url":"https://www.ncsc.gov.uk/guidance/shadow-it","locator":"Sections ''What is shadow IT?'', ''What can you learn from shadow IT?'' and ''Organisational mitigations''","access":"free"},{"title":"ChatGPT and large language models: what''s the risk?","publisher":"National Cyber Security Centre","year":2023,"url":"https://www.ncsc.gov.uk/blog-post/chatgpt-and-large-language-models-whats-the-risk","locator":"Section on whether queries are visible to the provider; recommendations","access":"free"},{"title":"AI and cyber security: what you need to know","publisher":"National Cyber Security Centre","year":2024,"url":"https://www.ncsc.gov.uk/guidance/ai-and-cyber-security-what-you-need-to-know","locator":"Section ''Questions to ask about the security of your organisation''s AI systems''","access":"free"},{"title":"UK GDPR, Article 32: Security of processing","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/32","locator":"Art. 32(1) and (4)","access":"free"},{"title":"UK GDPR, Article 28: Processor","publisher":"legislation.gov.uk","year":2016,"url":"https://www.legislation.gov.uk/eur/2016/679/article/28","locator":"Art. 28(1) and (3)","access":"free"},{"title":"Artificial Intelligence Playbook for the UK Government","publisher":"Government Digital Service","year":2025,"url":"https://www.gov.uk/government/publications/ai-playbook-for-the-uk-government/artificial-intelligence-playbook-for-the-uk-government-html","locator":"Principle 3; section ''Public AI applications and web services''","access":"free"},{"title":"AI adoption research","publisher":"Department for Science, Innovation and Technology","year":2026,"url":"https://www.gov.uk/government/publications/ai-adoption-research/ai-adoption-research","locator":"Methodology (limitations); qualitative findings on responsible use","access":"free"},{"title":"Trust, attitudes and use of artificial intelligence: A global study 2025","publisher":"University of Melbourne and KPMG International","year":2025,"url":"https://assets.kpmg.com/content/dam/kpmgsites/xx/pdf/2025/05/trust-attitudes-and-use-of-ai-global-report.pdf","locator":"Page 69 (PDF page 72); Figure 41 on page 71; executive summary (PDF page 8)","access":"free"},{"title":"2024 Work Trend Index Annual Report: AI at work is here. Now comes the hard part","publisher":"Microsoft and LinkedIn","year":2024,"url":"https://www.microsoft.com/en-us/worklab/work-trend-index/ai-at-work-is-here-now-comes-the-hard-part","locator":"First finding, on employees bringing their own AI to work","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('7.8', '["**What it measures.** Whether the organisation knows which human skills it must keep as AI takes over tasks, and has a way of keeping them in use.","**Why it matters.** Skills that are not practised fade. Researchers describe the irony: automate the routine and \"you deprive the user of the routine opportunities to practice their judgement\", so people are unprepared when the exception arrives. Those harmed are the customers and colleagues who rely on a human check that no longer works, and the junior staff who never learn the craft.","**The UK position.** No UK law addresses loss of skill through AI. Employers must take employees'' capabilities into account when entrusting tasks, and must train them when new technology brings new risks, but those duties concern health and safety. The Health and Safety Executive expects refresher training for infrequent, complex or safety-critical tasks. Aviation met the problem first: a Civil Aviation Authority paper warned that crews relying on automation might lose manual flying skills, and the United States regulator later asked airlines to make room for manual flying.","**What good looks like.** For each significant automation, a recorded decision on what people must still be able to do and how that is kept up: rotation through manual cases, deliberate practice, checks. Capability is tested, not assumed.","**Reading the answer.** An assurance that people would cope, offered without evidence, is the weak answer. Ask when the manual process was last run.","**A defensible figure.** In a 2026 trial, not yet peer reviewed, 52 software developers learned a new tool; those given AI assistance scored 17% lower on a test of understanding afterwards."]'::jsonb, false, '[{"title":"The Management of Health and Safety at Work Regulations 1999, regulation 13: Capabilities and training","publisher":"legislation.gov.uk","year":1999,"url":"https://www.legislation.gov.uk/uksi/1999/3242/regulation/13","locator":"Reg. 13(1) and (2)(b)(iii)","access":"free"},{"title":"Human factors: Training and competence","publisher":"Health and Safety Executive","year":2026,"url":"https://www.hse.gov.uk/humanfactors/topics/competence.htm","locator":"Section ''Key principles in competence''","access":"free"},{"title":"CAA Paper 2004/10: Flight Crew Reliance on Automation","publisher":"Civil Aviation Authority","year":2004,"url":"https://www.caa.co.uk/publication/download/12922","locator":"Executive Summary, page v","access":"free"},{"title":"Safety Alert for Operators 13002: Manual Flight Operations","publisher":"Federal Aviation Administration","year":2013,"url":"https://www.faa.gov/sites/faa.gov/files/other_visit/aviation_industry/airline_operators/airline_safety/SAFO13002.pdf","locator":"Discussion, page 1","access":"free"},{"title":"The Impact of Generative AI on Critical Thinking: Self-Reported Reductions in Cognitive Effort and Confidence Effects From a Survey of Knowledge Workers","publisher":"Hao-Ping (Hank) Lee and others, Carnegie Mellon University and Microsoft Research (CHI 2025)","year":2025,"url":"https://www.microsoft.com/en-us/research/wp-content/uploads/2025/01/lee_2025_ai_critical_thinking_survey.pdf","locator":"Abstract and Introduction, page 1","access":"free"},{"title":"How AI Impacts Skill Formation","publisher":"Judy Hanwen Shen and Alex Tamkin (arXiv preprint 2601.20245)","year":2026,"url":"https://arxiv.org/pdf/2601.20245","locator":"Abstract, page 1; results, page 2; section 4.3 for the sample","access":"free"},{"title":"Your Brain on ChatGPT: Accumulation of Cognitive Debt when Using an AI Assistant for Essay Writing Task","publisher":"Nataliya Kosmyna and others, MIT Media Lab (arXiv preprint 2506.08872)","year":2025,"url":"https://arxiv.org/pdf/2506.08872","locator":"Abstract, PDF page 2","access":"free"},{"title":"The Future of Jobs Report 2025","publisher":"World Economic Forum","year":2025,"url":"https://reports.weforum.org/docs/WEF_Future_of_Jobs_Report_2025.pdf","locator":"Key findings, page 6","access":"free"}]'::jsonb, '2026-10-02')
  on conflict (criterion_id) do update set body = excluded.body, is_sample = excluded.is_sample, sources = excluded.sources, checked = excluded.checked, updated_at = now();
insert into briefings (criterion_id, body, is_sample, sources, checked) values ('8.1', '["**What it measures.** Whether the organisation knows which customers, lenders and public buyers must report on sustainability, which duties reach it as a supplier, and what each may ask.","**Why it matters.** A reporting duty placed on a large company travels down to its suppliers as questionnaires. A firm caught by surprise answers with guesses, and guessed figures pass into reports that investors, lenders and the public rely on. That includes the energy its AI tools use. The EU legislator recorded: \"There is evidence that undertakings in the value chain, including small and medium-sized enterprises, receive disproportionate requests for information from reporting undertakings\".","**The UK position.** No UK law was found that limits what a customer may ask. An EU customer must report only if it exceeds both EUR 450 million net turnover and 1,000 employees (Directive (EU) 2026/470). Financial Conduct Authority rules require listed companies to report against UK Sustainability Reporting Standards for periods from 1 January 2027, with value-chain emissions on a comply-or-explain basis. Quoted and large companies must report energy and carbon. Central government asks bidders for a Carbon Reduction Plan on contracts above £5 million a year.","**What good looks like.** A written map: each major customer, lender and public buyer; the duty it is under; the data it may legitimately ask for; revised when clients or thresholds change.","**Reading the answer.** Knowing who the big customers are is not knowing their obligations. Ask for the map and its date. One drawn before 2026 is out of date.","**A defensible figure.** The European Commission estimates that the 2026 directive cut the number of companies in scope of mandatory EU sustainability reporting by about 85% (staff working document SWD(2026) 500, printed page 3)."]'::jsonb, true, '[{"title":"Directive (EU) 2026/470 amending Directives 2006/43/EC, 2013/34/EU, (EU) 2022/2464 and (EU) 2024/1760 (the Omnibus I Directive)","publisher":"Publications Office of the European Union (Official Journal of the European Union)","year":2026,"url":"http://publications.europa.eu/resource/cellar/2f337274-12b4-11f1-8870-01aa75ed71a1.0006.03/DOC_1","locator":"Recital 12; Article 2(1), (4) and (5), amending Articles 1(3), 19a and 29a of Directive 2013/34/EU; Article 3, amending Article 5(2) of Directive (EU) 2022/2464; Articles 5 and 6","access":"free"},{"title":"Commission Staff Working Document SWD(2026) 500 final, accompanying the two delegated regulations of 3 July 2026","publisher":"European Commission","year":2026,"url":"https://ec.europa.eu/finance/docs/level-2-measures/csrd-staff-working-document-2026-500_en.pdf","locator":"Section on the context of the ESRS revision, PDF page 4 (printed page 3); section 2.3, PDF page 10 (printed page 9); passage on the value chain cap, PDF page 6 (printed page 5)","access":"free"},{"title":"Directive (EU) 2025/794 as regards the dates from which Member States are to apply certain corporate sustainability reporting and due diligence requirements (the ''stop-the-clock'' Directive)","publisher":"Publications Office of the European Union (Official Journal of the European Union)","year":2025,"url":"http://publications.europa.eu/resource/cellar/8a789948-1a5f-11f0-b1a3-01aa75ed71a1.0006.03/DOC_1","locator":"Article 1 (amending Article 5(2) of Directive (EU) 2022/2464); Article 3 (transposition by 31 December 2025)","access":"free"},{"title":"Corporate sustainability reporting","publisher":"European Commission, Directorate-General for Financial Stability, Financial Services and Capital Markets Union","year":2026,"url":"https://finance.ec.europa.eu/capital-markets-union-and-financial-markets/company-reporting-and-auditing/company-reporting/corporate-sustainability-reporting_en","locator":"Sections ''What the EU is doing and why'' and ''Policy making timeline'' (entries for 14 April 2025, 30 July 2025, 9 December 2025 and 3 July 2026)","access":"free"},{"title":"PS26/19: Aligning listed issuers'' sustainability disclosures with international standards","publisher":"Financial Conduct Authority","year":2026,"url":"https://www.fca.org.uk/publications/policy-statements/ps26-19-aligning-listed-issuers-sustainability-disclosures-international-standards","locator":"Sections ''Who this is for'' and ''Next steps''","access":"free"},{"title":"UK Sustainability Reporting Standards","publisher":"Department for Business and Trade","year":2026,"url":"https://www.gov.uk/guidance/uk-sustainability-reporting-standards","locator":"Section ''What the UK is doing''","access":"free"},{"title":"Companies Act 2006, section 414CA: Non-financial and sustainability information statement","publisher":"legislation.gov.uk","year":2022,"url":"https://www.legislation.gov.uk/ukpga/2006/46/section/414CA","locator":"s.414CA(A1), (1), (1A), (2A), (3) and (4)","access":"free"},{"title":"Streamlined Energy and Carbon Reporting (SECR) regulations: evaluation","publisher":"Department for Energy Security and Net Zero","year":2026,"url":"https://www.gov.uk/government/publications/streamlined-energy-and-carbon-reporting-secr-regulations-evaluation","locator":"Landing page, ''Details''; report reference RAF019/2425 (112 pages)","access":"free"},{"title":"PPN 006: Taking account of Carbon Reduction Plans in the procurement of major government contracts","publisher":"Cabinet Office","year":2025,"url":"https://www.gov.uk/government/publications/ppn-006-taking-account-of-carbon-reduction-plans-in-the-procurement-of-major-government-contracts/ppn-006-taking-account-of-carbon-reduction-plans-html","locator":"Paragraphs 3, 4 and 11; footnote 5","access":"free"},{"title":"Modernising corporate reporting: consultation document","publisher":"Department for Business and Trade","year":2026,"url":"https://assets.publishing.service.gov.uk/media/6aa913c42344967b89b087ed/modernising-corporate-reporting-consultation-document.pdf","locator":"Paragraphs 6, 149 to 150 and 154 to 158 (PDF pages 42 to 43)","access":"free"}]'::jsonb, '2026-10-02')
