insert into briefings (criterion_id, body, is_sample, sources, checked) values ('8.2', '["**What it measures.** Whether the organisation can produce the basic data set that the EU''s voluntary standard defines: energy, emissions, water, waste, workforce, safety, pay and conduct.","**Why it matters.** Customers and lenders build their own public reports on suppliers'' numbers. A firm that reconstructs its figures for each questionnaire gives different answers to different askers, and nobody can tell which is right. The people misled are those who rely on the customer''s report. Energy used by AI systems is part of the footprint and is easily left out.","**The UK position.** The Basic Module is EU law, not UK law: Annex I to Commission Delegated Regulation (EU) 2026/1560, published on 21 September 2026, which supersedes the Commission''s 2025 Recommendation of EFRAG''s standard. It has eleven disclosures, B1 to B11. The regulation says: \"This module is the target approach for micro-undertakings and constitutes a minimum requirement for other undertakings\". Several environmental items are voluntary for firms with ten employees or fewer. No UK equivalent for small firms was found: energy and carbon reporting binds quoted and large companies, and government encourages others to report voluntarily.","**What good looks like.** One maintained data set covering B1 to B11, a named owner, the method noted beside each figure, and a yearly refresh.","**Reading the answer.** Energy bills in a folder are fragments. Ask when the set was last refreshed and whether the emissions method is written down. The standard asks for comparatives from the second year.","**A defensible figure.** The Commission''s staff estimate the first-year cost of the Basic Module at EUR 3,500 to 4,500 for firms with fewer than 20 employees and EUR 7,500 to 12,800 for firms with 20 to 250 (SWD(2026) 500, printed page 20)."]'::jsonb, false, '[{"title":"Commission Delegated Regulation (EU) 2026/1560 establishing sustainability reporting standards for voluntary use by undertakings protected by the value chain cap","publisher":"Publications Office of the European Union (Official Journal of the European Union)","year":2026,"url":"http://publications.europa.eu/resource/cellar/db614b12-b555-11f1-81de-01aa75ed71a1.0006.03/DOC_1","locator":"Article 2 and Article 4; recitals 3 and 5; Annex I, paragraphs 2, 6 to 8, 14, 18 and 24 to 43 (Basic Module, B1 to B11)","access":"free"},{"title":"Commission Staff Working Document SWD(2026) 500 final, accompanying the two delegated regulations of 3 July 2026","publisher":"European Commission","year":2026,"url":"https://ec.europa.eu/finance/docs/level-2-measures/csrd-staff-working-document-2026-500_en.pdf","locator":"Section 4.3.2 ''Quantified impacts of the VS'', text and table, PDF page 21 (printed page 20); footnote 37","access":"free"},{"title":"Commission Recommendation (EU) 2025/1710 on a voluntary sustainability reporting standard for small and medium-sized undertakings","publisher":"Publications Office of the European Union (Official Journal of the European Union)","year":2025,"url":"http://publications.europa.eu/resource/cellar/6e6d1165-7196-11f0-bf4e-01aa75ed71a1.0006.03/DOC_1","locator":"Recitals 8, 11 and 15 to 17; Annex I","access":"free"},{"title":"Voluntary sustainability reporting standard for non-listed SMEs (VSME)","publisher":"EFRAG","year":2024,"url":"https://www.efrag.org/sites/default/files/sites/webpublishing/SiteAssets/VSME%20Standard.pdf","locator":"Paragraphs 5, 22 to 44 (Basic Module, B1 to B11), in particular paragraphs 30, 31 and 42(b)","access":"free"},{"title":"Voluntary reporting standard for SMEs (VSME): concluded project page","publisher":"EFRAG","year":2024,"url":"https://www.efrag.org/en/projects/voluntary-reporting-standard-for-smes-vsme/concluded","locator":"Opening paragraphs; ''VSME Digital Template and XBRL Taxonomy''","access":"free"},{"title":"Commission adopts revised sustainability reporting standards","publisher":"European Commission, Directorate-General for Financial Stability, Financial Services and Capital Markets Union","year":2026,"url":"https://finance.ec.europa.eu/news/commission-adopts-revised-sustainability-reporting-standards-2026-07-03_en","locator":"News article, paragraphs on the voluntary reporting standard and on scrutiny","access":"free"},{"title":"Environmental reporting guidelines: including Streamlined Energy and Carbon Reporting requirements","publisher":"Department for Energy Security and Net Zero; Department for Environment, Food and Rural Affairs; Department for Business, Energy and Industrial Strategy","year":2019,"url":"https://www.gov.uk/government/publications/environmental-reporting-guidelines-including-mandatory-greenhouse-gas-emissions-reporting-guidance","locator":"Landing page, ''Details''; guidance PDF (152 pages), chapter 2, page 29, and chapter 3 on voluntary reporting","access":"free"},{"title":"2026 post-implementation review of the SECR regulations 2018","publisher":"Department for Energy Security and Net Zero","year":2026,"url":"https://assets.publishing.service.gov.uk/media/6a0dbf75faac4bc0b0e906af/2026-streamlined-energy-and-carbon-reporting-post-implementation-review.pdf","locator":"''Objective 4: Proportionate reporting burden'', pages 18 to 19, including Figure 3","access":"free"},{"title":"UK government conversion factors for company reporting of greenhouse gas emissions","publisher":"Department for Energy Security and Net Zero","year":2026,"url":"https://www.gov.uk/government/collections/government-conversion-factors-for-company-reporting","locator":"Collection page, opening summary; ''Conversion factors 2026''","access":"free"}]'::jsonb, '2026-10-02')
