insert into briefings (criterion_id, body, is_sample, sources, checked) values ('8.4', '["**What it measures.** Whether the organisation knows the legal limit on what a large customer may demand for its own sustainability report, and uses it.","**Why it matters.** A small supplier facing a large customer rarely feels able to say no. Each request answered beyond the limit becomes the baseline for the next, and data produced under pressure is often guessed. The harm falls on the smaller firm''s staff and on everyone who relies on the customer''s report.","**The UK position.** The right is EU law; no UK equivalent was found. Directive (EU) 2026/470 provides: \"Protected undertakings shall have the right to decline to provide information exceeding the information specified in the voluntary standards\". It applies to requests made for the customer''s reporting under that directive, not for due diligence or other purposes. Contract terms to the contrary are not binding, and a customer asking for more must say which items go further and that the supplier may decline. Annex II to Delegated Regulation (EU) 2026/1560 lists the datapoints inside the limit, for financial years from 1 January 2027. Member states must transpose the directive by 19 March 2027.","**What good looks like.** A written position: requests checked against the list; those beyond it declined with the provision cited and the standard data offered instead; requests and refusals logged.","**Reading the answer.** Ask for one refusal and the basis it stated. Check who was asking: the right applies to companies reporting under the EU directive, not to every customer or bank.","**A defensible figure.** A protected undertaking is one in a reporting company''s value chain that does not exceed an average of 1,000 employees in the preceding financial year (Directive 2013/34/EU, Article 19a(3), as amended)."]'::jsonb, false, '[{"title":"Directive (EU) 2026/470 amending Directives 2006/43/EC, 2013/34/EU, (EU) 2022/2464 and (EU) 2024/1760 (the Omnibus I Directive)","publisher":"Publications Office of the European Union (Official Journal of the European Union)","year":2026,"url":"http://publications.europa.eu/resource/cellar/2f337274-12b4-11f1-8870-01aa75ed71a1.0006.03/DOC_1","locator":"Article 2(4)(b), inserting new subparagraphs into Article 19a(3) of Directive 2013/34/EU (and Article 2(5) for the matching text in Article 29a(3)); Article 2(8), new Article 29ca; recital 12; Article 5(1); Article 6","access":"free"},{"title":"Commission Delegated Regulation (EU) 2026/1560 establishing sustainability reporting standards for voluntary use by undertakings protected by the value chain cap","publisher":"Publications Office of the European Union (Official Journal of the European Union)","year":2026,"url":"http://publications.europa.eu/resource/cellar/db614b12-b555-11f1-81de-01aa75ed71a1.0006.03/DOC_1","locator":"Article 1, Article 3 and Article 4; recitals 4 to 6; Annex II ''List of disclosures covered by the value chain cap''","access":"free"},{"title":"Commission Delegated Regulation C(2026) 5011 final: explanatory memorandum","publisher":"European Commission","year":2026,"url":"https://ec.europa.eu/finance/docs/level-2-measures/csrd-delegated-act-2026-5011_en.pdf","locator":"Explanatory memorandum, section 1 (PDF pages 2 to 3) and section 3 (PDF pages 5 to 6)","access":"free"},{"title":"Commission Staff Working Document SWD(2026) 500 final, accompanying the two delegated regulations of 3 July 2026","publisher":"European Commission","year":2026,"url":"https://ec.europa.eu/finance/docs/level-2-measures/csrd-staff-working-document-2026-500_en.pdf","locator":"Passage on the value chain cap, PDF page 6 (printed page 5); section 4.1, PDF pages 19 to 20 (printed pages 18 to 19)","access":"free"},{"title":"Implementing and delegated acts: Corporate Sustainability Reporting Directive","publisher":"European Commission, Directorate-General for Financial Stability, Financial Services and Capital Markets Union","year":2026,"url":"https://finance.ec.europa.eu/regulation-and-supervision/financial-services-legislation/implementing-and-delegated-acts/corporate-sustainability-reporting-directive_en","locator":"Section ''Latest'', entries dated 3 July 2026","access":"free"},{"title":"Commission adopts revised sustainability reporting standards","publisher":"European Commission, Directorate-General for Financial Stability, Financial Services and Capital Markets Union","year":2026,"url":"https://finance.ec.europa.eu/news/commission-adopts-revised-sustainability-reporting-standards-2026-07-03_en","locator":"News article, paragraph on the voluntary reporting standard","access":"free"},{"title":"Commission Recommendation (EU) 2025/1710 on a voluntary sustainability reporting standard for small and medium-sized undertakings","publisher":"Publications Office of the European Union (Official Journal of the European Union)","year":2025,"url":"http://publications.europa.eu/resource/cellar/6e6d1165-7196-11f0-bf4e-01aa75ed71a1.0006.03/DOC_1","locator":"Recitals 14 and 17; points 4 to 6 of the Recommendation","access":"free"},{"title":"PPN 006: Taking account of Carbon Reduction Plans in the procurement of major government contracts","publisher":"Cabinet Office","year":2025,"url":"https://www.gov.uk/government/publications/ppn-006-taking-account-of-carbon-reduction-plans-in-the-procurement-of-major-government-contracts/ppn-006-taking-account-of-carbon-reduction-plans-html","locator":"Paragraphs 3 and 13","access":"free"}]'::jsonb, '2026-10-02')
